% & \left.\left.+\sum_{n=1}^{N}\left({\frac{L_{n}C_{n}D_{n}}{f_{n}}}+\frac{(n+1)s}{b_{n}\log_{2}\left(1+\frac{p_{n}g_{n}}{b_{n}n_{0}}\right)}\right)\right)\right] \tag{28a} \label{eqn:28a}\\ 
