% & \left.\left.+\left({\frac{L_{m}C_{m}D_{m}}{f_{m}}}+\frac{s}{b_{m}\log_{2}\left(1+\frac{p_{m}g_{m}}{b_{m}n_{0}}\right)}\right)\right)\right] \tag{29a} \label{eqn:29a}\\ 
