\textit{\textbf{For the first block}}, \textbf{problem in (2)} is equivalently re-written as \vspace{-15pt}
\begin{subequations} 
\begin{align}
\min_{\delta_{n}^{k,r}} \quad & \sum_{k=1}^{K}\left[\max_{r \in \mathcal{R}} \left({\frac{L_{m}^{k}C_{m}^{k}D_{m}^{k}}{f_{m}^{k}}}+\frac{s}{b_{m}^{k}\log_{2}\left(1+\frac{p_{m}^{k}g_{m}^{k}}{b_{m}^{k}n_{0}}\right)}\right.\right. \nonumber\\
& \left.\left.+\sum_{n=1}^{N}\left({\frac{L_{n}C_{n}D_{n}}{f_{n}}}+\frac{\delta_{n}^{r,k}(n'+2)s}{b_{n}^{k}\log_{2}\left(1+\frac{p_{n}^{k}g_{n}^{k}}{b_{n}^{k}n_{0}}\right)}\right)\right)\right] \label{eqn:4a'}\\ 
\textrm{s.t.} \quad & 0 \leq \delta_{n}^{r,k} \leq 1, \forall{n}, \forall{r}, \forall{k}. \label{eqn:4b'}
\end{align}
\end{subequations} \vspace{-15pt}

In \eqref{eqn:4b'}, we have transformed binary routing variable of relay nodes into a continuous variable. Since the problem in (4) is already convex, it can be solved directly using convex optimization problem solvers. \textit{For complexity analysis}, this problem consists of $(N)$ scalar decision variables and $(N)$ linear constraints, which results in the per-iteration computational complexity of $\mathcal{O}\left((N)^2\sqrt{N}\right)$ \cite{ben2001lectures}.

\textit{\textbf{For the second block}},  let us introduce a new slack variable $x_{m}^{k}$ such that:

\vspace{-15pt}
\begin{equation}
x_{m}^{k} \geq \frac{s}{b_{m}^{k}\log_{2}\left(1+\frac{p_{m}^{k}g_{m}^{k}}{b_{m}^{k}n_{0}}\right)}, \forall{m}. 
\end{equation} 
\textbf{problem in (3)} is equivalently re-written as
\begin{subequations} 
\begin{align}
\min_{p_{m}^{k},f_{m}^{k}} \quad & \sum_{k=1}^{K}\left[\max_{r \in \mathcal{R}} \left({\frac{L_{m}^{k}C_{m}^{k}D_{m}^{k}}{f_{m}^{k}}}+x_{m}^{k}\right.\right. \nonumber\\
& \left.\left.+\sum_{n=1}^{N}\left({\frac{L_{n}^{k}C_{n}^{k}D_{n}^{k}}{f_{n}^{k}}}+\frac{\delta_{n}^{r,k}(n'+2)s}{b_{n}^{k}\log_{2}\left(1+\frac{p_{n}^{k}g_{n}^{k}}{b_{n}^{k}n_{0}}\right)}\right)\right)\right] \label{eqn:4a}\\ 
\textrm{s.t.} \quad & L_{m}^{k}\zeta_{m}C_{m}^{k}D_{m}^{k}{{f_{m}^{k}}^{2}}+x_{m}^{k}p_{m}^{k} \le E_{m}^{\max}, \forall{m} \label{eqn:4b}\\
& \frac{s}{b_{m}^{k}x_{m}^{k}} \leq \log_{2}\left(1+\frac{p_{m}^{k} g_{m}^{k}}{b_{m}^{k} n_{0}}\right), \forall{m} \label{eqn:4c}\\
& \eqref{eqn:2b}, \eqref{eqn:2d}. \label{eqn:4d}
\end{align}
\end{subequations}

We see that objective \eqref{eqn:4a} is convex, while constraints in \eqref{eqn:4d} are also convex. Now we focus on converting constraints \eqref{eqn:4b} and \eqref{eqn:4c} into convex ones.

\textit{Constraint \eqref{eqn:4b}}: For $x_{m}^{k}>0$ and $p_{m}^{k}>0$, we apply SCA to approximate $x_{m}^{k}p_{m}^{k}$ as

\begin{equation} \label{eqn:5}
x_{m}^{k} p_{m}^{k} \le \frac{1}{2} \frac{p_{m}^{k,i}}{x_{m}^{k,i}} {x_{m}^{k}}^{2} + \frac{1}{2} \frac{x_{m}^{k,i}}{p_{m}^{k,i}} {p_{m}^{k}}^{2} = h_{m}^{k,i}(x_{m}^{k},p_{m}^{k})
\end{equation}

\noindent
where $p_{m}^{k,i}$ and $x_{m}^{k,i}$ are the feasible point of $p_{m}^{k}$ and $x_{m}^{k}$ at iteration $i$. Hence constraint \eqref{eqn:4b} can be convexified as

\begin{equation} \label{eqn:6}
    L_{m}^{k}\zeta_{m}C_{m}^{k}D_{m}^{k}{{f_{m}^{k}}^{2}} +\frac{1}{2} \frac{p_{m}^{k,i}}{x_{m}^{k,i}} {x_{m}^{k}}^{2} + \frac{1}{2} \frac{x_{m}^{k,i}}{p_{m}^{k,i}} {p_{m}^{k}}^{2} \le E_{m}^{\max}, \forall{m}.
\end{equation}

\textit{Constraint \eqref{eqn:4c}}: We use this inequality
\begin{align} \label{eqn:34}
\ln(1+z) \ge \ln(1+z_{i}) + \frac{z_{i}}{z_{i}+1} - \frac{(z_{i})^{2}}{z_{i}+1} \frac{1}{z}.
\end{align}
Now we approximate RHS of \eqref{eqn:4c} as

\begin{equation} \label{eqn:8}
\begin{split}
    \frac{ s \ln 2}{b_{m}^{k}x_{m}^{k}} \leq \ln \left(1+\frac{p_{m}^{k,i} g_{m}^{k}}{b_{m}^{k} n_{0}}\right) + \frac{p_{m}^{k,i} g_{m}^{k}}{p_{m}^{k} g_{m}^{k}+b_{m}^{k} n_{0}} \\
    - \frac{(p_{m}^{k,i} g_{m}^{k})^{2}}{p_{m}^{k,i} g_{m}^{k} + b_{m}^{k} n_{0}} \frac{1}{p_{m}^{k} g_{m}^{k}}, \forall{m}.
\end{split}
\end{equation}

So, we solve the following convex problem at iteration $i+1$:
\begin{subequations} 
\begin{align}
\min_{p_{m}^{k},f_{m}^{k}} \quad & \sum_{k=1}^{K}\left[\max_{r \in \mathcal{R}} \left({\frac{L_{m}^{k}C_{m}^{k}D_{m}^{k}}{f_{m}^{k}}}+x_{m}^{k}\right.\right. \nonumber\\
& \left.\left.+\sum_{n=1}^{N}\left(\delta_{n}^{r,k}{\frac{L_{n}^{k}C_{n}^{k}D_{n}^{k}}{f_{n}^{k}}}+\frac{(n'+2)s}{\delta_{n}^{r,k}b_{n}^{k}\log_{2}\left(1+\frac{p_{n}^{k}g_{n}^{k}}{b_{n}^{k}n_{0}}\right)}\right)\right)\right] \label{eqn:9a}\\ 
\textrm{s.t.} \quad & \eqref{eqn:4d}, \eqref{eqn:6}, \eqref{eqn:8}. \label{eqn:9b}
\end{align}
\end{subequations}
\textit{For complexity analysis}, this problem consists of $(2M)$ scalar decision variables and $(4M)$ linear or quadratic constraints, which results in the per-iteration computational complexity of $\mathcal{O}\left((2M)^2\sqrt{4M}\right)$ \cite{ben2001lectures}.

\textit{\textbf{For the third block}}, let us introduce a new slack variable $y_{n}^{k}$ such that:
\begin{equation}
y_{n}^{k} \ge \frac{\delta_{n}^{r,k}(n'+2) s}{b_{n}^{k}\log_{2}\left(1+\frac{p_{n}^{k}g_{n}^{k}}{b_{n}^{k}n_{0}}\right)}, \forall{n}. 
\end{equation}
\textbf{problem in (3)} is equivalently re-written as

\begin{subequations} 
\begin{align}
\min_{p_{n}^{k},f_{n}^{k}} \quad & \sum_{k=1}^{K}\left[\max_{r \in \mathcal{R}} \left(\left({\frac{L_{m}^{k}C_{m}^{k}D_{m}^{k}}{f_{m}^{k}}}+\frac{s}{b_{m}^{k}\log_{2}\left(1+\frac{p_{m}^{k}g_{m}^{k}}{b_{m}^{k}n_{0}}\right)}\right)\right.\right. \nonumber\\
& \left.\left.+\sum_{n=1}^{N}\left({\frac{L_{n}^{k}C_{n}^{k}D_{n}^{k}}{f_{n}^{k}}}+y_{n}^{k}\right)\right)\right] \label{eqn:11a}\\ 
\textrm{s.t.} \quad & L_{n}^{k}\zeta_{n}C_{n}^{k}D_{n}^{k}{{f_{n}^{k}}^{2}}+y_{n}^{k}p_{n}^{k} \le E_{n}^{\max}, \forall{n} \label{eqn:11b}\\
& \frac{\delta_{n}^{r,k}(n'+2)s}{b_{n}^{k}y_{n}^{k}} \leq \log_{2}\left(1+\frac{p_{n}^{k} g_{n}^{k}}{b_{n}^{k} n_{0}}\right), \forall{n}. \label{eqn:11c}\\
& \eqref{eqn:2c}, \eqref{eqn:2e}. \label{eqn:11d} 
\end{align}
\end{subequations}

\noindent Here, the objective function \eqref{eqn:11a} and constraint in \eqref{eqn:11d} are convex. However, constraints \eqref{eqn:11b} and \eqref{eqn:11c} are still non-convex. For convexifying these two constraints, we follow the same strategy as for constraints \eqref{eqn:4b} and \eqref{eqn:4c}.

\textit{Constraint \eqref{eqn:11b}}: Similar to constraint \eqref{eqn:4b}, constraint \eqref{eqn:11b} can be convexified as
\begin{equation} \label{eqn:12}
    L_{n}^{k}\zeta_{n}C_{n}^{k}D_{n}^{k}{{f_{n}^{k}}^{2}} +\frac{1}{2} \frac{p_{n}^{k,i}}{y_{n}^{k,i}} {y_{n}^{k}}^{2} + \frac{1}{2} \frac{y_{n}^{k,i}}{p_{n}^{k,i}} {p_{n}^{k}}^{2} \le E_{n}^{max}, \forall{n}
\end{equation}
\noindent
where $p_{n}^{k,i}$ and $y_{n}^{k,i}$ are the feasible point of $p_{n}^{k}$ and $y_{n}^{k}$ at SCA iteration $i$. 

\textit{Constraint \eqref{eqn:11c}}: Similar to  constraint \eqref{eqn:4c}, we approximate RHS of \eqref{eqn:11c} as
\begin{equation} \label{eqn:13}
\begin{split}
    \frac{\delta_{n}^{r,k}(n'+2) s \ln{2}}{ b_{n}^{k} y_{n}^{k}} \le \ln \left(1+\frac{p_{n}^{k,i} g_{n}^{k}}{b_{n}^{k} n_{0}}\right) + \frac{p_{n}^{k,i} g_{n}^{k}}{p_{n}^{k} g_{n}^{k}+b_{n}^{k} n_{0}} \\
    - \frac{(p_{n}^{k,i} g_{n}^{k})^{2}}{p_{n}^{k,i} g_{n}^{k} + b_{n}^{k} n_{0}} \frac{1}{p_{n}^{k} g_{n}^{k}}, \forall{n}.
\end{split}
\end{equation}
Thus, we solve the following convex problem at iteration $i+1$:
\begin{subequations} 
\begin{align}
\min_{p_{n}^{k},f_{n}^{k}} \quad & \sum_{k=1}^{K}\left[\max_{r \in \mathcal{R}} \left(\left({\frac{L_{m}^{k}C_{m}^{k}D_{m}^{k}}{f_{m}^{k}}}+\frac{s}{b_{m}^{k}\log_{2}\left(1+\frac{p_{m}^{k}g_{m}^{k}}{b_{m}^{k}n_{0}}\right)}\right)\right.\right. \nonumber\\
& \left.\left.+\sum_{n=1}^{N}\left({\frac{L_{n}^{k}C_{n}^{k}D_{n}^{k}}{f_{n}^{k}}}+y_{n}^{k}\right)\right)\right] \label{eqn:14a}\\ 
\textrm{s.t.} \quad & \eqref{eqn:11d}, \eqref{eqn:12}, \eqref{eqn:13}. \label{eqn:14b}
\end{align}
\end{subequations}
\textit{For complexity analysis}, this problem consists of $(2N)$ scalar decision variables and $(4N)$ linear or quadratic constraints, which results in the per-iteration computational complexity of $\mathcal{O}\left((2N)^2\sqrt{4N}\right)$ \cite{ben2001lectures}.
To summarize, we jointly solve the above three blocks to obtain the solutions for \textbf{problem in (3)}, as illustrated in Algorithm 1.
