\begin{proof}[Proof of Theorem \ref{thm: stone weierstrass for functions}]
    Recall that the differentially-defined function $h$ is annotated with some IVP having provable global existence. Without loss of generality, further assume that the IVP starts at time $t_0 = 0$, i.e. it is of the form
    \begin{align*}
        &x' = f(x)\\
        &x(0) = X
    \end{align*}
    Since the IVP has global existence, its solution $\phi : \R \to \R^n$ is well-defined and Theorem \ref{thm: stone weierstrass for IVPs} applies. Consequently, we may compute polynomials $\theta^{+}(t), \theta^{-}(t) \in \Q^n[t]$ such that the following are provable
    \begin{align}
        x = X \land t = 0 &\rightarrow \dbox{x' = f(x), t' = 1 \& t \leq T}{\norm{x - \theta^{+}(t)}^2 < (\sfrac{\eps}{4})^2} \label{fml: fwd time approx}\\
        x = X \land t = 0 &\rightarrow \dbox{x' = -f(x), t' = -1 \& t \geq -T}{\norm{x - \theta^{-}(t)}^2 < (\sfrac{\eps}{4})^2} \label{fml: bwd time approx}
    \end{align}
    Let $p \in \Q[t]$ be any polynomial such that $\norm{p - h}_{[-T, T]} < \sfrac{\eps}{4}$ holds, which necessarily (computably) exists by the classical Stone-Weierstrass theorem. It then follows that the following are valid formulas of $\folr$ and therefore provable with axiom $\irref{qear}$. 
    \begin{align}
         0 \leq t \leq T &\rightarrow \abs{p(t) - \theta^+_0(t)} < \sfrac{\eps}{2} \label{fml: fwd time poly}\\
        -T \leq t \leq 0 &\rightarrow \abs{p(t) - \theta^-_0(t)} < \sfrac{\eps}{2} \label{fml: bwd time poly}
    \end{align}
    where $\theta^+_0, \theta^-_0$ denote the first-coordinate projections of $\theta^+$ and $\theta^-$ respectively. On the other hand, applying axiom \irref{FI} in conjunction with the formulas (\ref{fml: fwd time approx}), (\ref{fml: bwd time approx}) proves the following 
    \begin{align}
        0 \leq t \leq T &\rightarrow \abs{h(t) - \theta^+_0(t)} < \sfrac{\eps}{4} \label{fml: fwd time error bound}\\
        -T \leq t \leq 0 &\rightarrow \abs{h(t) - \theta^-_0(t)} < \sfrac{\eps}{4} \label{fml: bwd time error bound}
    \end{align}
    combining formulas (\ref{fml: fwd time error bound})+(\ref{fml: fwd time poly}) and (\ref{fml: bwd time error bound})+(\ref{fml: bwd time poly}) proves the following
    \begin{align*}
        0 \leq t \leq T &\rightarrow \abs{h(t) - p(t)} < \sfrac{3\eps}{4}\\
        -T \leq t \leq 0 &\rightarrow \abs{h(t) - p(t)} < \sfrac{3\eps}{4}
    \end{align*}
    which then combines to prove the desired formula (\ref{fml: error bound}). 
\end{proof}


\begin{proof}[Proof of Lemma \ref{lem: mont perturbations}]
    Let $\psi(\vec{x}, \vec{y})$ denote the quantifier-free part of $\phi(\vec{x})$ (recall that $\phi(\vec{x})$ is assumed to be in prenex normal form), where $\vec{x}$ are the free variables and $\vec{y}$ are the bound variables. By construction of the perturbations, it suffices to show that $\pertf[\F]{\psi}{\delta} \rightarrow \pertf[\G]{\psi}{\frac{\delta - \norm{\F}_I}{2}}$ is valid in $I$. This can be proven inductively by first inducting on the number of function terms and then on the structural complexity:
    \begin{itemize}
        \item The base case where $\phi$ does not contain functions is trivial, since perturbation is the identity in this case. 
        \item The cases of boolean connectives and quantifiers hold trivially by inductive hypothesis.
        \item Consider the non-trivial case of $\psi \equiv t(f(e), \vec{z}) \succeq 0$ where $\vec{z} = (\vec{x}, \vec{y})$ and the term $e(\vec{z})$ is function-free. The perturbations corresponding to $\F, \G$ are:
        \begin{align*}
            &\pert^\forall_{\F}\left(t(f(e), \vec{z}) \succeq 0, \delta\right) = \forall^{[-\delta, \delta] + \F_{f(e)}(e)} w~\pert^\forall_{\F_{w \mapsto f(e)}}\left(t(w, \vec{z}) \succeq 0, \delta\right)\\
            &\pert^\forall_{\G}\left(t(f(e), \vec{z}) \succeq 0, \frac{\delta - \norm{\F}_I}{2}\right) = \forall^{\left[-\frac{\delta - \norm{\F}_I}{2}, \frac{\delta - \norm{\F}_I}{2}\right] + \G_{f(e)}(e)} w~ \pert^\forall_{\G_{w \mapsto f(e)}}\left(t(w, \vec{z}) \succeq 0, \frac{\delta - \norm{\F}_I}{2}\right)
        \end{align*}
        By applying the inductive hypothesis on $t(w, \vec{z}) \succeq 0$ with enclosure $I_{w \mapsto f(e)}$, it suffices to show that $\abs{w - \G_{f(e)}(e)} \leq \frac{\delta - \norm{\F}_I}{2} \implies \abs{w - \F_{f(e)}(e)} \leq \delta$. To this end, let $w \in \R$ be a witness to $\abs{w - \G_{f(e)}(e)} \leq \frac{\delta - \norm{\F}_I}{2}$. Since $\G$ is $(I, \frac{\delta - \norm{\F}_I}{2})$ admissible, this necessarily implies that $\abs{w - f(e)} < \delta - \norm{\F}_I$. Consequently, the triangle inequality gives
        \[\abs{w - \F_{f(e)}(e)} \leq \abs{w - f(e)} + \norm{\F}_I < \delta\]
        which completes the proof by induction.
    \end{itemize}
    To obtain corresponding results for existential perturbations, one could either follow the proof above but use $\pert^\exists$ instead, or utilize Lemma \ref{lem: perturbation of negated formulas} and directly apply duality.  
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem: encode predicates as formulas}]
    Let $R \subseteq \N^n$ be a computable predicate. First construct a computable function $f: [0, 1]^n \to \R$ satisfying $f(\alpha(\vec{m})) > 0 \iff R(\vec{m})$ as follows:
    \begin{enumerate}
        \item For $\vec{m} \in \N^n$, define $f(\alpha(\vec{m})) = \frac{1}{\norm{\vec{m}}}\chi_{R}(\vec{m})$, where $\norm{\vec{m}}$ denotes the standard Euclidean norm, and $\chi_R : \N^n \to \{0, 1\}$ is the characteristic function of $R$. I.e. $\chi_R(\vec{m}) = 1 \iff \vec{m} \in R$.

        \item As $([\alpha(i), \alpha(i + 1)))_{i \in \N}$ forms a partition of $[0, 1)$, it follows that $\left(\prod_{1 \leq i \leq n} [\alpha(\vec{m}_i), \alpha(\vec{m}_i + 1))\right)_{\vec{m} \in \N^n}$ forms a partition of $[0, 1)^n$. For each box of the form $\prod_{1 \leq i \leq n} [\alpha(\vec{m}_i), \alpha(\vec{m}_i + 1))$, define $f$ on $\prod_{1 \leq i \leq n} [\alpha(\vec{m}_i), \alpha(\vec{m}_i + 1))$ by multilinear interpolation from the vertices. I.e. For $\vec{x} \in \prod_{1 \leq i \leq n} [\alpha(\vec{m}_i), \alpha(\vec{m}_i + 1))$, $f(\vec{x})$ is the weighted average of the values of $f$ at the vertices of the box $\prod_{1 \leq i \leq n} [\alpha(\vec{m}_i), \alpha(\vec{m}_i + 1))$, which are already defined, note that this interpolation procedure is computable. Doing this for all boxes defines a computable function $f: [0, 1)^n \to \R$. 

        \item For $\vec{x} \in [0, 1]^n \setminus [0, 1)^n$, define $f(\vec{x}) = 0$. Note that this preserves the continuity of $f$, since for any sequence of points $(z_k)_k \to \vec{x}$ with $(z_k)_k \subseteq [0, 1)^n$, it is necessarily the case that the vectors $\vec{m}$ in part (1) of the construction which forms the vertices of the box that $z_i$ belongs to diverges to $\infty$ in norm. From this it follows by construction that $f(z_i)_i \to 0$. 

        It remains to verify that $f$ is still computable. To this end, let $\vec{x} \in [0, 1]^n$ be arbitrary, $(\vec{q}_i)_{i \in \N} \subseteq \Q^n$ be a name of $\vec{x}$ and $k \in \N$ be arbitrary. To prove that $f$ is computable, it suffices to (uniformly) compute some $q \in \Q^n$ such that $\abs{q - f(\vec{x})} < 2^{-k}$. This can be achieved by first searching for some finite index $n_1 \in \N$ such that at least one of the following is true:
            \begin{itemize}
                \item $B(\vec{q}_{n_1}, 2^{-n_1}) \cap [0, 1]^n \subseteq [0, 1)^n$ I.e. $\vec{q}_{n_1}$ witnesses $\vec{x} \in [0, 1)^n$, $f(\vec{x})$ can then be computed by the computable procedure in construction (2).

                \item For all $\vec{y} \in B(\vec{q}_{n_1}, 2^{-n_1}) \cap [0, 1)^n$, it is the case that $\norm{\vec{m}} > 2^{k}$, where $\vec{m} \in \N^n$ characterizes the box that $\vec{y}$ belongs to in the sense of (2). In this case, we can simply output the desired value $q$ as $q = 0$. This is because $\vec{x} \in B(\vec{q}_{n_1}, 2^{-n_1})$, so either $\vec{x} \in [0, 1]^n \setminus [0, 1)^n$, in which case $f(\vec{x})$ is defined to be $0$. Or $\vec{x} \in B(\vec{q}_{n_1}, 2^{-n_1}) \cap [0, 1)^n$, so the value of $f$ at the vertices of $\vec{x}$ will all be smaller than $2^{-k}$ as $f(\vec{x}) \leq \frac{1}{\norm{\vec{m}}} < 2^{-k}$.
            \end{itemize}
        It therefore remains to show that such an $n_1$ exists. Notice that if $\vec{x} \in [0, 1)^n$ holds, then some such $n_1$ necessarily exists. So suppose that $\vec{x} \in [0, 1]^n \setminus [0, 1)^n$, then the sequence $\vec{q}_n$ converges to some element in $[0, 1]^n \setminus [0, 1)^n$. Suppose for the sake of contradiction that the second condition does not hold for all $n_1$, then this gives a sequence $(\vec{y}_i)_i \subseteq [0, 1)^n$ converging to $\vec{x}$ such that the norms $\norm{\vec{m}_i}$ does not diverge where $\vec{m}_i \in \N^n$ are the corners of $\vec{y}_i$'s, contradicting the construction of $\alpha(\vec{m})$. Hence, such a $n_1$ necessarily exists, and the search is therefore computable. 
    \end{enumerate} 
    The construction yields a computable function $f : [0, 1]^n \to \R$ such that $R(\vec{m}) \iff f(\alpha(\vec{m})) > 0$. However, recall that $\L_C$ only allows for univariate functions, yet $f$ is $n$-ary. To this end, let $\rho : [0, 1] \to [0, 1]^n$ denote the computable space-filling curve given by Lemma \ref{lem: space-filling curve}, and denote by $\rho_i$ the natural (computable) projections for $1 \leq i \leq n$. As $f$ is computable, it follows that the function $h \coloneqq f \circ \rho : [0, 1] \to \R$ is computable as well. Without loss of generality, we may further computably extend $h$'s domain to all of $\R$ \cite[Extension Theorem]{Pour-El_Richards_2017}. It then follows by construction that the following equivalences hold:
    \[R(\vec{m}) \iff f(\alpha(\vec{m})) > 0 \iff \exists^{[0, 1]}y \left(\bigwedge_{1 \leq i \leq n} \rho_i(y) = \alpha_i(\vec{m}) \land h(y) > 0\right)\]
    which is a bounded formula in the language $\L_C$, completing the proof. 
\end{proof}


