    grow                    = right,
    sibling distance        = 3em,
    level distance          = 5em,
    edge from parent/.style = {draw, -latex},
    every node/.style       = {font=\footnotesize},
    sloped
  ]
  \node [root] {S}
  child { node [env] {BC}
    child { node [root] {B}
      child { node [env] {RD}
        child { node [root] {R} }
        child { node [root] {D} }
