\section{Shape Derivative} \label{shape Derivative}
The shape derivative or gradient \cite{debreuve2007using,aubert2003image} measures how the energy functional changes with respect to changes in the shape of the domain. It tells us how sensitive the shape functional is to small variations or deformations in the shape.\\
Consider the domain $\Omega\subset \mathbb{R}^{3}$ and $\Gamma$ represents the boundary of the domain and $T_{t}$ be the family transformation  defined by  
\begin{equation}
    T_{t}:\mathbb{R}^3 \longrightarrow \mathbb{R}, \quad t\in [0,\epsilon )
\end{equation}
$T_{t}$ maps the point $X\in \Omega$ onto $x\in \Omega_{t}$, where $T_{t}(\Omega)=\Omega_{t}$.
Let $V(t,x)$ be the velocity at the point $x(t)$, defined by 
\begin{equation}
    V(t,x)=\frac{\partial x}{\partial t}(t,T^{-1}_{t}(x))
\end{equation}
Define the shape derivative \cite{Sokolowski1992,chicco2017shape,dogan2007discrete} of a functional $J$ in the direction of the vector field $V$ as follows:
\begin{equation}\label{shape derivative}
    dJ(\Omega;V)=\lim_{t\rightarrow 0} \frac{1}{t}(J(\Omega_{t})-J(\Omega)).
\end{equation}
Let $\Gamma$ be of class $C^{2}$ and $\phi\in W^{2,1}(\mathbb{R}^{3})$. Consider the functional 
\begin{equation}
    J(\Gamma)=\int_{\Gamma}\phi\  d\Gamma
\end{equation}
is shape differentiable for perturbation vector field $V\in C_{0}^{1}(\mathbb{R}^{2};\mathbb{R}^{2})$ with shape differentiable functional
\begin{equation} \label{dJ1}
    dJ(\Gamma;V)=\int_{\Gamma}(\nabla \phi \cdot V +\phi\  \text{div}_{\Gamma}V)\ d\Gamma.
\end{equation}
Similarly, if $\Gamma$ be of class $C^{2}$ and $\phi\in W^{2,2}(\mathbb{R}^{3})$. Then the functional \cite{Sokolowski1992},
\begin{equation} 
J(\Omega)=\int_{\Gamma}(\nabla \phi \cdot \hat{n})^{2} d\Gamma
\end{equation}
is shape differentiable for perturbation vector field $V\in C_{0}^{1}(\mathbb{R}^{2};\mathbb{R}^{2})$ with
\begin{equation} \label{dJ2}
dJ(\Gamma;V)=\int_{\Gamma} \left\{2 \frac{\partial \phi}{\partial \hat{n}} [D^{2}\phi] \hat{n} \cdot \hat{n}+H\left|\frac{\partial \phi}{\partial \hat{n}}\right|^{2}+2 \text{div}_{\Gamma}\left(\frac{\partial \phi}{\partial \hat{n}}\nabla_{\Gamma}\phi\right)\right\}V\cdot \hat{n} \ d\Gamma
\end{equation}
\section{Gradient Descent Method}
The shape gradient method is a deformable technique used to reconstruct a 2D simple manifold in the form of triangulated surface from a given level set. A triangulated sphere serves as the initial approximated to target the  surface, which is then deformed against the direction of the shape gradient, denoted as $-\overrightarrow{dE}$, computed via gradient descent method.
That is,
\begin{equation}
dE(\Gamma;V)=\langle {\overrightarrow{dE(\Gamma)},V} \rangle
\end{equation} 
Let $\Gamma_{0}=\Gamma(V_{0},T)$ represent the initial surface, where $V_{0}$ encompasses all vertices of the triangles on the initial triangulated mesh surface $\Gamma_{0}$, and $T$ consists of all triangular elements. In each iteration, the vertex set $V_{0}$ is updated utilizing the gradient descent minimization method, defined as:
\begin{equation}
V_{n+1}=V_{n}-\overrightarrow{dE}(\Gamma)
\end{equation}

%Here, $\hat{n}$ signifies the weighted unit normal vector to the vertex on the surface $\Gamma_{n}$, while $dE$ represents the Riesz element for the shape derivative map of the energy function $E(\Gamma)$. 
This iterative process terminates when $V_{n+1}\approx V_{n}$, achieving a minimum energy state.

\subsection{Mathematical Model}
Let $\Omega\subset \mathbb{R}^{3}$ be the domain, $\Gamma$ denotes its boundary, and $\phi$ represent the signed distance function associated with an object within $\Omega$. The energy functional is defined as:
\begin{equation}
E(\Gamma)=\int_{\Gamma}(\alpha\ \phi^{2}(\Gamma)+\beta\ |\nabla_{\Gamma}\phi|^{2})d\Gamma \label{Model}
\end{equation}
Here, $\alpha$, $\beta$  are constants and $\phi$ is fixed level set. The term $\phi^{2}(\Gamma)$ is to ensure the surface $\Gamma$ stays closer to zero level set, the term $|\nabla_{\Gamma}\phi|^{2}$ ensures the surface $\Gamma$ assumes  a constant level, may also be a nonzero. Considering $|\nabla_{\Gamma}\phi|^{2}=|\nabla\phi|^2-(\nabla\phi \cdot \hat{n})^{2}$, where $\hat{n}$ is the unit normal vector to the surface $\Gamma$, the energy functional \ref{Model} simplifies to:
\begin{equation}
E(\Gamma)=\int_{\Gamma}( \alpha \ \phi^{2}(\Gamma)+\beta \ |\nabla\phi|^2-\beta \ (\nabla\phi \cdot \hat{n})^{2})d\Gamma
\end{equation}
Now the objective is to minimize $E(\Gamma)$ using shape gradient descent method. Notably, since $\phi$ is zero on the object's surface, $E(\Gamma)$ is ideally minimum when $\phi=0$ and, level set gradient and normal of the surface $(\Gamma)$ are parallel. The first term in \ref{Model} aids in locating the boundary, while the second term promotes the smoothness of the deformable surface $\Gamma$. Utilizing \ref{dJ1} and \ref{dJ2}, the energy functional $E(\Gamma)$ is shape-differentiable for any vector field $V$. Considering $V$ as the unit normal vector $\hat{n}$ around the surface $\Gamma$, the shape gradient of \ref{Model} is given by:

%\begin{equation} \label{dJ}
%\begin{aligned}
%    \langle dE ; \hat{n} \rangle = & \int_{\Gamma} \left\{ \left( \nabla \phi^{2} + \nabla |\nabla \phi|^{2} \right) \cdot \hat{n} + H\left( \phi^{2} + |\nabla\phi|^2 - \left|\frac{\partial\phi}{\partial\hat{n}}\right|^2 \right) \right. \\
%    & \left. - 2\frac{\partial\phi}{\partial\hat{n}} \left( \nabla\phi \cdot \left( ^{*}[D\hat{n}]\hat{n}+[D\hat{n}]\hat{n} \right) - [D^{2}\phi] \hat{n}\cdot \hat{n} \right) \right\} d\Gamma
%\end{aligned}
%\end{equation}

\begin{equation} \label{dJ}
\begin{aligned}
    dE(\Gamma;\hat{n}) = & \int_{\Gamma} \left\{ \left( \nabla \phi^{2} + \nabla |\nabla \phi|^{2} \right) \cdot \hat{n} + H\left( \phi^{2} + |\nabla\phi|^2 - \left|\frac{\partial\phi}{\partial\hat{n}}\right|^2 \right) \right. \\
    & \left. - 2\frac{\partial\phi}{\partial\hat{n}} \left( \nabla\phi \cdot \left( ^{*}[D\hat{n}]\hat{n}+[D\hat{n}]\hat{n} \right) - [D^{2}\phi] \hat{n}\cdot \hat{n} \right) \right\} d\Gamma
\end{aligned}
\end{equation}
Here, $H$ denotes the Mean curvature, $[D\hat{n}]$ signifies the gradient (tensor) of the vector $\hat{n}$ , and $^{*}[D\hat{n}]$ denotes the conjugate transpose of $[D\hat{n}]$. Note that, $[D\hat{n}]\hat{n}=0$ for the unit normal $\hat{n}$ on the paraboloid \ref{paraboloid}. Hence $dE$ is the Riesz representative  vector element as follows.
\begin{equation} \label{dJ_finel}
\begin{aligned}
    \langle \overrightarrow{dE(\Gamma)} , \hat{n} \rangle = & \int_{\Gamma} \left\{ \left( \nabla \phi^{2} + \nabla |\nabla \phi|^{2} \right) \cdot \hat{n} + H\left( \phi^{2} + |\nabla\phi|^2 - \left|\frac{\partial\phi}{\partial\hat{n}}\right|^2 \right) \right. \\
    & \left. - 2\frac{\partial\phi}{\partial\hat{n}} \left(  [D^{2}\phi] \hat{n}\cdot \hat{n} \right) \right\}\hat{n}\cdot \hat{n}\ d\Gamma
\end{aligned}
\end{equation}

