The PDF is a function of $(\tilde{\y},\tilde{\z})$, and is given by 
\begin{equation}
\label{eqn:globaldualKmn}
\rho(\tilde\y,\tilde\z) \propto \prod_{(i,j) \in \E} \tilde{f}_{i,j}(\tilde{y}_i, \tilde{z}_j)
\prod_{i \in [m]} \tilde{g}_{i}(\tilde{y}_{i})\prod_{i \in [n]} \tilde{h}_{i}(\tilde{z}_{i})
\end{equation}
which can also be written as
\begin{equation}
\label{eqn:ModelDualPDF2}
\rho(\tilde\y,\tilde\z)   =  \frac{1}{|2\pi \pmb{\Sigma}_\rho|^{1/2}}\textrm{exp}\Big(-\frac{ \ 1\ }{ \ 2\ }
\begin{bmatrix}
\tilde{\y} \\
\tilde{\z}
\end{bmatrix}^\intercal
\!\pmb{\Sigma}^{-1}_{\rho}
\begin{bmatrix}
\tilde{\y} \\
\tilde{\z}
\end{bmatrix}
\,\Big)
\end{equation}
where $\pmb{\Sigma}_\rho^{-1} \in \R^{(m+n)\times (m+n)}$
decomposes into 
\begin{equation}
\label{eqn:AplusB}
\pmb{\Sigma}^{-1}_{\rho} = \mathbf{A} + \mathbf{B}
\end{equation}

Here $\mathbf{A}$ is a diagonal matrix with entries
\begin{equation}
%\label{eqn:K2}
\mathbf{A}_{i, i} = \left\{ \begin{array}{ll}
       \dfrac{1}{\sigma_i^2} + \displaystyle\sum_{t=1}^n\cfrac{1}{s_{i,t}^2}, & \text{if $1\le i \le m$} \\[3ex]
       \dfrac{1}{\tau_i^2} + \displaystyle\sum_{t=1}^m\cfrac{1}{s_{t,j}^2}, & \text{if $m+1\le i \le m+n$}
      \end{array}\right.   
\end{equation}
and $\mathbf{B}$ is a block anti-diagonal matrix with the following form\footnote{Indeed, a graph $\G$ is bipartite iff there exists a labeling of $\V$ that gives rise 
to an adjacency matrix with the structure in~(\ref{eqn:BMatrix}), see~\cite[Chapter 2]{asratian1998bipartite}.} 
\begin{equation}
\label{eqn:BMatrix}
\mathbf{B}  = \begin{bNiceArray}{@{\hspace*{8pt}}cc@{\hspace*{8pt}}}[cell-space-limits=2pt]
  \mathbf{0}_{m\times m} & \mathbf{C}_{m\times n}  \\[0.8ex]
  \mathbf{C}_{n\times m}^\intercal & \mathbf{0}_{n\times n}
\end{bNiceArray}
\end{equation}
with $\mathbf{C}_{i,j} = -1/s_{i,j}^2$. 

Fig.~\ref{fig:Primalfactors} shows the normal factor graph of the PDF in~(\ref{eqn:globaldualKmn}). 
The boxes labeled ``$+$" are equality indicator factors~(\ref{eqn:Definition2}) and the boxes 
labeled ``$=$" represent zero-sum indicator factors~(\ref{eqn:Definition1}). The 
factors~(\ref{eqn:tildegl}), (\ref{eqn:tildehl}), and (\ref{eqn:tildefl}) are represented by the small 
empty boxes. The symbol ``$\circ$" denotes a sign inversion.

