The eigenvalues of $\mathbf{A}$ are 
$1/\sigma^2 + n/s^2$ with multiplicity $2n$. To compute the eigenvalues of $\mathbf{B}$,
we look at
\begin{equation}
\label{eqn:IMPrimal}
\mathbf{B}^2  =\frac{n}{s^4}\begin{bNiceArray}{@{\hspace*{8pt}}cc@{\hspace*{8pt}}}[cell-space-limits=2pt, columns-width=auto]
 \mathbf{J}_{n}  & \mathbf{0}_{n\times n}  \\[1.0ex]
  \mathbf{0}_{n\times n} & \mathbf{J}_{n}
\end{bNiceArray}
\end{equation}
The eigenvalues of $\mathbf{B}^2$ are zero with multiplicity $2n-2$ and $n^2/s^4$ with multiplicity two. 
Therefore, the eigenvalues of $\mathbf{B}$ are zero with multiplicity $2n-2$, $n/s^2$, and $-n/s^2$.

The eigenvalues of $\pmb{\Sigma}^{-1}_{\rho}$ are the addition of the eigenvalues of $\mathbf{A}$ and $\mathbf{B}$. 
Hence
\begin{IEEEeqnarray}{rCl}
|\pmb{\Sigma}^{-1}_{\rho}| &=& \prod_{i=1}^{2n} \lambda_i\\
& = & \cfrac{1}{\sigma^2}\big(\cfrac{1}{\sigma^2}+\cfrac{2n}{s^2}\big)\big(\cfrac{1}{\sigma^2}+\cfrac{n}{s^2}\big)^{2n-2}
\label{eqn:SigmaDeterm}
\end{IEEEeqnarray}

After applying the scale factor (\ref{eqn:SigmaXtoW}), we obtain
\begin{equation}
|\pmb{\Sigma}^{-1}_{\pi}| = \big(s^2 + 2n\sigma^2\big)(s^2 + n\sigma^2)^{2(n-1)}s^{2(n-1)^2}
\end{equation}
In the limit $n \to \infty$
\begin{equation}
\label{eqn:SigmaDetermLimit}
\lim_{n \to \infty}\frac{\ln|\pmb{\Sigma}_{\pi}|}{n^2} = -2\ln(s)
\end{equation}

Fig.~\ref{fig:SigmaBoundPlot} shows $\ln|\pmb{\Sigma}_{\pi}|/n^2$ as a function of $n^2$ for $\K_{n,n}$ with 
$s^2 = 2$ and $\sigma^2 = 1$. The blue dashed line shows the limit in (\ref{eqn:SigmaDetermLimit}),
which is equal to $-\ln(2)$ in this example.



\section{A Special Case: $\K_{1,n}$}
\label{sec:NFGK1N}

This section examines the complete bipartite graph $\K_{1,n}$, also known as the \emph{star} graph. 
Since $\K_{1,n}$ is cycle-free, the normalization constants in (\ref{eqn:ModelPrimalPDF2}) and (\ref{eqn:ModelDualPDF2}) can be computed 
via the Gaussian belief propagation algorithm~\cite{Weiss1999correctness}. Consequently, $|\pmb{\Sigma}_{\rho}|$ and $|\pmb{\Sigma}_{\pi}|$ can be
calculated efficiently. 

As in Section~\ref{sec:NFGEquiv}, we assume that $\X_{\phantom{1}}^\intercal = (X_1, X_2, \ldots, X_n)$ are 
represented by the edges of the graph. In the star graph
\begin{equation}
Z + X_1  + X_2 + \ldots + X_{n} = 0
\end{equation}
as illustrated in Fig.~\ref{fig:Dualfactors}. 

The PDF $\pi(\x)$ defined on $\K_{1,n}$ is 
as follows
\begin{equation}
\label{eqn:piforK1n}
\pi(\x)  \propto h(z)\prod_{i \in [n]} f_{i}(x_{i})g_i(x_i)  
\end{equation}
where 
\begin{equation}
f_{i}(x_{i})  =  \frac{1}{\sqrt{2\pi s^i_{e}}}\textrm{exp}\Big(-\frac{s^2_{i}x_i^2}{2}\Big)
\end{equation}
and
\begin{equation}
g_{i}(x_{i})  =  
\frac{1}{\sqrt{2\pi \sigma^2_{i}}}\textrm{exp}\big(-\frac{\sigma^2_{i}x_{i}^2}{2}\big)
\end{equation}
for $1 \le i \le n$, and
\begin{IEEEeqnarray}{rCl}
h(z) & = & \frac{1}{\sqrt{2\pi \tau^2_{i}}}\textrm{exp}\big(-\frac{\tau^2z^2}{2}\big) \\[1ex]
	& = & \frac{1}{\sqrt{2\pi \tau^2_{i}}}\textrm{exp}\Big(-\frac{\tau^2(x_1+x_2+\ldots+x_{n})^2}{2}\Big)
\end{IEEEeqnarray}

The corresponding precision matrix $\pmb{\Sigma}_\pi^{-1} \in \R^{n\times n}$ is 
\begin{equation}
\pmb{\Sigma}_{\pi\,i,j}^{-1}= \left\{ \begin{array}{ll}
        s_{i}^2 + \sigma_i^2 + \tau^2, & \text{if $i=j$} \\[1ex]
       \tau^2, & \text{otherwise.}
      \end{array}\right.   
\end{equation}

In the dual model
\begin{equation}
\label{eqn:rhoforK1n}
\rho(\tilde\y,\tilde z) \propto \tilde{h}(\tilde{z})\prod_{i \in [n]} \tilde{f}_{i}(\tilde{y}_i, \tilde{z})
\tilde{g}_{i}(\tilde{y}_{i})
\end{equation}
where
\begin{equation}
\label{eqn:flk1nd}
\tilde{f}_{i}(\tilde{y}_i, \tilde{z})  =  \textrm{exp}\Big(-\frac{(\tilde{y}_i - \tilde{z})^2}{2s^2_{i}}\Big)
\end{equation}
and
\begin{equation}
\label{eqn:gl}
\tilde{g}_{i}(\tilde{y}_{i})  =  
\textrm{exp}\big(-\frac{\tilde{y}_{i}^2}{2\sigma^2_{i}}\big)
\end{equation}
for $1 \le i \le n$, and
\begin{equation}
\label{eqn:gl}
\tilde{h}(\tilde{z})  =  
\textrm{exp}\big(-\frac{\tilde{z}^2}{2\tau^2}\big)
\end{equation}


The precision matrix $\pmb{\Sigma}^{-1}_{\rho} \in \R^{(n+1)\times (n+1)}$ %associated with $\rho(\tilde\y,\tilde z)$
is a symmetric positive-definite arrowhead matrix\footnote{An arrowhead matrix is a square matrix containing zeros in all entries except for the last row, the last column, and 
the main diagonal~\cite[p. 64]{watkins2010fundamentals}.} with the following structure
\begin{equation}
\label{eqn:ArrowDual}
\pmb{\Sigma}^{-1}_{\rho}  =  \begin{bNiceArray}{@{\hspace*{8pt}}cc@{\hspace*{8pt}}}[cell-space-limits=2pt]
  \mathbf{D} & \mathbf{v}  \\[0.8ex]
  \mathbf{v}_{\phantom{1}}^\intercal & c
\end{bNiceArray}
\end{equation}
Here $\mathbf{D} \in \R^{n\times n}$ is a diagonal matrix with entries
\begin{equation}
\label{eqn:DMPrimal}
\mathbf{D}_{i,i} = \cfrac{1}{\sigma^2_{i}} + \cfrac{1}{s_{i}^2}
\end{equation}
The vector $\mathbf{v} \in \R^{n}$ is given by
\begin{equation}
\label{eqn:AMPrimal}
\mathbf{v}_i =  -\cfrac{1}{s^2_{i}}
\end{equation}
and the scalar $c \in \R$ is
\begin{equation}
\label{eqn:cPrimal}
c = \cfrac{1}{\tau^2} + \sum_{i \in [n]}\cfrac{1}{s_{i}^2}
\end{equation}

