\title{Price of Anarchy for Congestion and Scheduling Games via Vector Fitting}
\author{Danish Kashaev \footnote{\texttt{danish.kashaev@cwi.nl}, Centrum Wiskunde \& Informatica, Amsterdam}}

\date{\today}

\begin{document}
