\subsection{The recognition algorithm}\label{sec:recognition}
%
Testing whether a given graph $G$ is $1$-metric antidimensional can be done by using the ADIM-1 algorithm provided in  Figure~\ref{alg:ADIM1}. This algorithm works as follows. At line~\ref{l:distances}, the all-pairs distances are computed. Then, the input graph is analyzed starting from each vertex $v$. In detail, the set $S$ is initially set as $S=\{v\}$. This set is intended as a potential $k$-ARS for $G$, for some $k\ge 1$. The while-loop at lines~\ref{l:while}--\ref{l:update-S} is responsible for computing for which $k$ the set $S$ is a $k$-ARS. If $k>1$ (see line~\ref{l:test-k}), $G$ is not $1$-metric antidimensional and hence the algorithm stops returning ``False'' (i.e., $\Adim(G) > 1$) and $k$. In such a case, $k$ is intended as a lower bound for the $k$-metric antidimensionality of $G$. Otherwise, when $k=1$, the algorithm adds all the sets in $\mathcal{Z}_S$ having cardinality $1$ to $S$ (see line~\ref{l:compute-Zi}), and repeats until $S=V(G)$. If the algorithm does not stop after checking all the vertices in $V(G)$, then it returns ``True'' (i.e., $\Adim(G) = 1$).


% ---------------------- ALGO start
\begin{algorithm}[h]
\SetKwInput{Proc}{Algorithm}
\Proc{ADIM-1}
\SetKwInOut{Input}{Input}
\Input{An arbitrary graph $G$}
\SetKwInOut{Output}{Output}
\Output{True if and only if $\Adim(G)=1$}

\BlankLine
\BlankLine

    Compute the distance matrix of $G$ in $O\left(n^3\right)$ time using the Floyd-Warshall algorithm~\cite[p. 629]{CLR90} \label{l:distances}\;

    $S\leftarrow\emptyset$
    \tcp*[r]{we assume $S$ is a $k$-ARS for some $k\ge 1$} \label{l:init-S-empty}

    \ForEach{ $v_i\in V(G)$ \label{l:foreach-v} }{
        $S=\left\{ v_i \right\}$ \label{l:init-S-v}\;

        \While{ $\big(V\setminus S\neq\emptyset\big)$ \label{l:while} }{

            compute $k=\min\{|Z^i|\,:\,Z^i\in \mathcal{Z}_S\}$ \label{l:compute-k} \;

            \If{ $k>1$ \label{l:test-k} }{
                \KwRet (False, $k$)
                \tcp*[r]{$k$ is a lower bound for the $k$-metric antidimension of $G$}
             }
            \Else{
                let $Z^{i_1},\dots,Z^{i_\ell}$ be all equivalence classes in $\mathcal{Z}_S$ such that $\left|Z^{i_1}\right|=\dots=\left|Z^{i_\ell}\right|=1$ \label{l:compute-Zi}\;

                $S\,\leftarrow\,S\cup \left( \cup_{t=1}^\ell Z^{i_t} \right)$ \label{l:update-S} \;
            }
        }
    }
    \KwRet True \;
\caption{ Algorithm checking whether $\Adim(G)=1$.}
\label{alg:ADIM1}
\end{algorithm}
% ---------------------- ALGO end

Algorithm ADIM-1 might indeed be seen as a special case of~\cite[Algorithm II]{Chatterjee-2019}, when looking for $1$-antidimensional graphs, and we refer the reader to this work for its correctness and computational time, which is $O(n^4)$.

