\subsection{Frame-to-Submap Pose Optimization as Odometry}
\label{sec:Pose Optimisation}
% \kaicheng{
%         \begin{itemize}
%                 \item Main objective Function
%                 \item Jacobian of the objective Function
%                 \item Notice: Since the spherical harmonics coefficient is not optimised during the pose estimation, the Jacobian matrix about spherical harmonics coefficients is not discussed here, it can be discussed in the extension paper
%         \end{itemize}
% }

% We borrow the idea of \cite{kerl2013robust} to do the pose estimation, the differences are \cite{kerl2013robust} using the intensity of RGB to calculate the  while we are using the height value,
% and \cite{kerl2013robust} using the camera model to project 3D points on the 2D image but we are

The LiDAR pose of the current scan relative to the previous scan is formulated as a frame-to-submap pose optimization problem. It minimizes the errors between the projected heights of the {raw} scan patches and the heights of their corresponding submap patches reconstructed from the CURL's spherical harmonics functions.
% Therefore, we formulate the optimization problem with the function of spherical harmonics.

Suppose there are $K$ patches in $\mathbb{M}_j$ associated with the submap patches and
% ${}_{\mathtt{L}_j}\mathbf{p}_i^k\in {}_{\mathtt{L}_j}\mathbb{P}^k$ 
${}_{\mathtt{L}_j}\mathbf{p}_i^k \in {}_{\mathtt{L}_j}\mathbf{P}^k$
denotes the $i$th point in patch $M^k$.
% and the $i$th point is ${}_{\mathtt{L}}\mathbf{P}_{M^k}\in {}_{\mathtt{L}}\mathbf{P}_{M^k}$.
% $\mathbb{M}^k\in \mathbb{M}$ is $k$th patch paired to ${}_{\mathtt{L}}\mathbf{P}_{M^k}$ store in the map {$\mathbb{S}$}.
The objective function to be minimized is formulated as
\begin{equation}
	\begin{aligned}
		e(\bm{\xi})             & = \sum_{k=1}^{K} \sum_{i} \left | \left|
		{\mathsf{P}_z}(\mathsf{Q})
		-\mathbf{I}^k(\bm{\mu})\right | \right|^2                                                                                                                          \\
		\text{with}\ \mathsf{Q} & =\mathbf{T}_{\mathtt{W}\mathtt{M}_k}^{-1}\mathbf{T}_{\mathtt{W}\mathtt{L}_{j-1}} \mathsf{Exp}(\bm{\xi})\ {}_{\mathtt{L}_j}\mathbf{p}_i^k
	\end{aligned}
	\label{eq:residual function}
\end{equation}
where $\bm{\xi} \in \mathfrak{se}(3)$ is the Lie algebra of the 6-DoF relative pose from $\mathtt{L}_{j}$ to $\mathtt{L}_{j-1}$, $\mathsf{Exp}(\cdot)$ is the exponential map, ${\mathsf{P}_z}([x,y,z]^T)=z$, and $\mathbf{I}^k(\bm{\mu})$ is the height of the corresponding point reconstructed using the spherical harmonics:
\begin{equation}
	\begin{aligned}
		\mathbf{I}^k(\bm{\mu}) & = \sum_{l=0}^{L}\sum_{m = -l}^{l}c_{l,m}^kY_{l,m}\bigl(\theta(y),\phi(x)\bigr) \\
		\text{with}\ \bm{\mu}  & = \mathsf{P}_{xy}(\mathsf{Q})
	\end{aligned}
	\label{eq:I^k}
\end{equation}
where $c_{l,m}^k \in \mathbf{c}^k$ is the spherical harmonics coefficient of patch $M^k$, and ${\mathsf{P}_{xy}}([x,y,z]^T)=[x,y]^T$.
% \begin{equation}
%         \bm{\mu}=\Gamma \left( \mathbf{T}_{\mathtt{W}\mathtt{M}_k}^{-1}\mathbf{T}_{\mathtt{W}\mathtt{L}_{j-1}} \mathsf{Exp}(\bm{\xi})\
%         {}_{\mathtt{L}}\mathbf{P}_{M^k} \right)
%         \label{eq:mu}
% \end{equation}
% where ${\mathsf{P}_{xy}}([x,y,z]^T)=[x,y]^T$.
% \begin{equation}
%         \mathbf{T}_{\mathtt{W}\mathtt{M}_k}^{-1}= (\mathbf{T}_{\mathtt{L}_j\mathtt{M}_k})^{-1} (\mathbf{T}_{\mathtt{W}\mathtt{L}_j})^{-1}
%         \label{eq:^OT_L^k}
% \end{equation}
% Since the mapping function in \eqref{eq:conformal mapping} only works for ${}_{\mathtt{M}_k}\mathbf{P}$ which point cloud was used to generate $k$th patch only, it can not provide a solution for unknown points. Thus, the natural neighbor interpolation \cite{cgal:eb-23b} uses in \eqref{eq:mu} as well.
Note $\mathbf{T}_{\mathtt{W}\mathtt{M}_k}$ can be derived from the patch's attributes defined in Section \ref{sec:data association}. % as \textcolor{blue}{$\mathbf{T}_{\mathtt{W}\mathtt{M}_k}=\mathbf{T}_{\mathtt{W}\mathtt{L}}\mathbf{T}_{\mathtt{L}\mathtt{M}_q}$ where $\mathtt{M}_k$'s corresponding patch in the map is $\mathtt{M}_q$}.
Hence, \eqref{eq:residual function} computes the sum of errors between the projected heights of the patches in the current LiDAR scan $j$ and the heights of the reconstructed submap patches. Intuitively, referring to Fig. \ref{fig:pose optimisation}, if the projected heights {are} considered as pixel intensities, this {is} similar to minimizing photometric errors in visual odometry and SLAM systems. \cite{kerl2013robust,forster2014svo,luo2022hybrid}.
Since $e({\bm{\xi}})$ is non-linear with respect to $\bm{\xi}$, its Jacobian matrix is required. % For the sake of simplicity, 
The Jacobian matrix of the residual $r_{k,i}(\bm{\xi})$ inside $||\cdot||^2$ of \eqref{eq:residual function} is
\begin{equation}
	\mathbf{J} = \frac{\partial r_{k,i}(\bm{\xi})}{\partial \bm{\xi}}=
	\mathbf{J}^{\mathsf{P}_z}
	\mathbf{J}^ {\mathsf{Q}}
	- \mathbf{J}^ {\mathbf{I}^k}
	\mathbf{J}^ {\mathsf{P}_{xy}}
	\mathbf{J}^ {\mathsf{Q}}
	\label{eq:Jac}
\end{equation}
and according to  (\ref{eq:lemma1}) in Lemma 1
\begin{equation}
	\small
	\mathbf{J}^ {\mathsf{Q}} =
	\left[
		\begin{matrix}
			\mathbf{R}_{\mathtt{W}\mathtt{M}_k}^{-1}
			\mathbf{R}_{\mathtt{W}\mathtt{L}_{j-1}} \mathsf{Exp}(\bm{\theta}) &
			-\mathbf{R}_{\mathtt{W}\mathtt{M}_k}^{-1}
			\mathbf{R}_{\mathtt{W}\mathtt{L}_{j-1}} \mathsf{Exp}(\bm{\theta})[{}_{\mathtt{L}_j}\mathbf{p}_i^k]_{\times}
		\end{matrix}
		\right]
\end{equation}
{here, $\bm{\theta}$ denotes the rotational component of the $\bm{\xi}$, which is able to be written as $\bm{\xi} = [\bm{\rho}, \bm{\theta}]^\top \in \mathbb{R}^6$, where $\bm{\rho}$ represents the translational part.}
More details of these Jacobian terms are given in the Appendix A.
The Levenberg-Marquardt method is used to solve the optimization problem.

