\textbf{Lemma 1.} For a transformation matrix $\mathbf{T} = \left[
		\begin{matrix}
			\mathbf{R} & \mathbf{t} \\
			\mathbf{0} & 1
		\end{matrix}
		\right]
	\in SE(3) \subset \mathbb{R}^{4\times 4}$, which acts on a point $\mathbf{p} \in \mathbb{R}^{3 \times 1}$, such that $\mathbf{T} \cdot \mathbf{p} = \mathbf{R}\mathbf{q} + \mathbf{t}$. The Jacobian matrix $\mathbf{J}_{\mathbf{T}}^{\mathbf{T \cdot q}}$ is given by:
\begin{equation}
	\mathbf{J}_{\mathbf{T}}^{\mathbf{T \cdot q}} = \left[ \mathbf{R} \quad -\mathbf{R} [\mathbf{p}]_{\times} \right]
	\label{eq:lemma1}
\end{equation}
where $[\cdot]_{\times}$ is the skew-symmetric matrix of the vector.

\textbf{Lemma 2.} For the transformation matrices $\mathbf{T}_1 = \left[
		\begin{matrix}
			\mathbf{R}_1 & \mathbf{t}_1 \\
			\mathbf{0}   & 1
		\end{matrix}
		\right]
	\in SE(3) \subset \mathbb{R}^{4\times 4}$ and $\mathbf{T}_2 = \left[
		\begin{matrix}
			\mathbf{R}_2 & \mathbf{t}_2 \\
			\mathbf{0}   & 1
		\end{matrix}
		\right]
	\in SE(3) \subset \mathbb{R}^{4\times 4}$, which act on a point $\mathbf{p} \in \mathbb{R}^{3\times 1}$, the Jacobian matrix $\mathbf{J}_{\mathbf{T}_2}^{\mathbf{T}_1\mathbf{T}_2^{-1}\cdot \mathbf{p}}$ is given by:

\begin{equation}
	\mathbf{J}_{\mathbf{T}_2}^{\mathbf{T}_1\mathbf{T}_2^{-1}\cdot \mathbf{p}} =
	\left[
	-\mathbf{R}_1 \quad \mathbf{R}_1[\mathbf{T}_2^{-1} \cdot \mathbf{p}]_{\times}
	\right]
	\label{eq:lemma2}
\end{equation}


\textbf{Lemma 3.} For function $Y_{l,m}(\theta, \phi)$, its Jacobian matrix $\mathbf{J}^{y_{l,m}}$ is

\begin{equation}
	\begin{aligned}
		\mathbf{J}^{Y_{l,m}} = \left[
		\mathbf{J}_{\phi}^{Y_{l,m}}\quad
		\mathbf{J}_{\theta}^{Y_{l,m}}
		\right] \in \mathbb{R}^{1\times 2}
	\end{aligned}
	\label{eq:J_Y}
\end{equation}

\begin{equation}
	\begin{aligned}
		\mathbf{J}_{\phi}^{Y_{l,m}} =
		\sqrt{\frac{2l+1}{4\pi}\frac{(l-|m|)!}{(l+|m|)!}}P_{l,|m|}(\cos\theta)
		\cdot \\
		\left\{
		\begin{array}{cc}
			-m\sqrt{2}\sin(m\phi), & m>0 \\
			0,                     & m=0 \\
			-m\sqrt{2}\cos(m\phi), & m<0
		\end{array}
		\right.
	\end{aligned}
	\label{eq:J_Y_phi}
\end{equation}

\begin{equation}
	\small
	\begin{aligned}
		\mathbf{J}_{\theta}^{Y_{l,m}} = \left\{
		\begin{array}{ll}
			mcot\theta Y_{l,m}(\theta,\phi)-                                                    \\
			\sqrt{\frac{2l+1}{4\pi}\frac{(l-m)!}{(l+m)!}}N_m(\phi) P_{l,m+1}(\cos\theta), & m>0 \\
			\frac{-\sqrt{l(l+1)}}{N_1(\phi)}Y_{l,1}(\theta,\phi)\ or                            \\
			-\sqrt{\frac{2l+1}{4\pi}}P_{l,1}(cos \theta),                                 & m=0 \\
			-mcot\theta Y_{l,m}(\theta,\phi)-                                                   \\
			\sqrt{\frac{2l+1}{4\pi}\frac{(l+m)!}{(l-m)!}}N_m(\phi)P_{l,1-m}(cos\theta),   & m<0
		\end{array}
		\right.
	\end{aligned}
	\label{eq:J_Y_theta}
\end{equation}

\eqref{eq:J_Y_theta} is derived according to \eqref{eq:Legendre} from \cite{bosch2000computation}.

\begin{equation}
	\label{eq:Legendre}
	sin\theta \frac{dP_{l,m}}{d\theta} = m cos\theta P_{l,m} - sin\theta P_{l,m+1}
\end{equation}







