\section{Tokenization-Agnostic Lexicon Construction}\label{apx:tokenization_agnostic_lexicon}

\begin{algorithm}[ht]
{\fontsize{9}{9}\selectfont
\begin{algorithmic}[1]
\State $q_\mathrm{start} \gets \text{new state}$, $Q \gets \{q_\mathrm{start}\}$, $F \gets \{\}$
\State $\delta \gets \text{empty transition function}$
\For{$w \in \Gamma$}
    \State $\mathrm{cur} \gets q_\mathrm{start}$
    \For{$c \in w$}
        \State $q' \gets \text{new state}$
        \State $Q \gets Q \cup \{q'\}$
        \If{$c \text{ is last character of } w$}
            \State $\delta \gets \delta \cup \{(\mathrm{cur}, c, w, q')\}$ \Comment{Arc emitting $w$}
        \Else
                \State $\delta \gets \delta \cup \{(\mathrm{cur}, c, \varepsilon, q')\}$
        \EndIf
        \State $\mathrm{cur} \gets q'$
    \EndFor
    \State $q' \gets \text{new state}$
    \State $Q \gets Q \cup \{q'\}$
    \State $\delta \gets \delta \cup \{(\mathrm{cur}, \varepsilon, w, q')\}$
    \State $F \gets F \cup \{q'\}$ \Comment{$q'$ is end of word}
\EndFor
\State $\mathcal{T} \gets \varepsilon\textsc{-Close}(\textsc{Determinize}((\Sigma, \Gamma, Q, q_\mathrm{start}, F, \delta)))$ \label{line:minimize}
\State \Return $\mathcal{T}$ 
\end{algorithmic}
}
\caption{%
    \hspace{-1mm}: Lexicon Construction\newline
    \textbf{Inputs}: Subword Vocabulary $\Sigma \subseteq \Gamma \subset \Sigma^+$
}
\label{alg:lexicon_construction}
\end{algorithm}

\section{MaxMatch Transducer Construction}\label{apx:maxmatch_algorithms}
We briefly reintroduce the terminology from \cite{song-etal-2021-fast}.
Let $\Gamma$ be a subword vocabulary, and let $T$ be a trie with state space $V$ such that each state in the trie corresponds to a prefix of a token in $\Gamma$. Let $v \in V$ be a state in the trie corresponding to prefix $w_1w_2\dots w_k$. Define two functions $f(v) : V \rightarrow V \cup \{\texttt{null} \}$, the failure link function, and $F(v) : V \rightarrow \Gamma^*$, the failure pop function. $f(v)$ computes the state $v$ which corresponds to the suffix $w_kw_{k+1}\dots w_n$ that remains after chunking $w_1w_2\dots w_{k-1}$ into tokens $t_1, t_2, \dots t_l$ where $t_i \in \Gamma$ and each corresponds to the longest possible matching token at each step. Then, $F(v) = [t_1, t_2, \dots t_k]$. Algorithm \ref{alg:failure_construction} does not differentiate between marked and unmarked subwords (e.g., \texttt{token} vs \texttt{\#\#token}), but can easily be extended to handle this case.

\begin{minipage}{0.47\textwidth}
\begin{algorithm}[H]
{\centering \fontsize{9}{9}\selectfont
\begin{algorithmic}[1]
\State $\mathrm{root} \gets \Call{Node}{\null}$ \Comment{Build a trie representing $\Gamma$}
\For{$w \in \Gamma$}
    \State $\mathrm{cur} \gets \mathrm{root}$
    \For{$c \in w$}
        \If{$c \notin \mathrm{cur}.\mathrm{children}$}
            \State $\mathrm{cur}.\mathrm{children}[c] \gets \Call{Node}{\null}$
            \State $\mathrm{cur}.\mathrm{children}[c].\mathrm{str} \gets \mathrm{cur}.\mathrm{str} + c$
        \EndIf
        \State $\mathrm{cur} \gets \mathrm{cur}.\mathrm{children}[c]$
    \EndFor
    \State $\mathrm{cur}.\mathrm{final} = \texttt{True}$ \Comment{Corresponds to $w \in \Gamma$}
\EndFor

\State $\mathrm{queue} \gets [\mathrm{root}]$ \Comment{Begin computing failure arcs}

\While{$\mathrm{queue}$ is not empty}
    \State $\mathrm{cur} \gets \mathrm{queue}.\textsc{Dequeue}()$
    \For{$c \in \mathrm{cur}.\mathrm{children}$}
        \State $v \gets \mathrm{cur}.\mathrm{children}[c]$
        \If{$v.final$}
            \State $f(v) \gets r$
            \State $F(v) \gets [\mathrm{cur}.\mathrm{str}]$
        \Else
            \State $z \gets f(\mathrm{cur})$
            \State $Z \gets []$
            \While{$z \ne \texttt{null}$}
                \State $\textsc{Extend}(Z, F(z))$
                \State $z \gets f(z)$
            \EndWhile
            \If{$z \ne \texttt{null}$}
                \State $f(v) \gets z.\mathrm{children}[c]$
                \State $F(v) \gets \textsc{Extend}(F(\mathrm{cur}), Z)$
            \EndIf
        \EndIf
    \State $\mathrm{queue}.\textsc{Enqueue}(v)$
    \EndFor
\EndWhile
\State \Return $\mathrm{root}, f, F$
\end{algorithmic}
}
\caption{%
\hspace{-1mm}: Failure Function Computation \cite{song-etal-2021-fast} \\
    \textbf{Input}: Vocabulary $\Gamma$ \\
    \textbf{Outputs}: Trie $\mathrm{root}$, Failure Functions $f/F$
}
\label{alg:failure_construction}
\end{algorithm}
\end{minipage}
\hfill
\begin{minipage}{0.47\textwidth}
\begin{algorithm}[H]
{\centering \fontsize{9}{9}\selectfont
\begin{algorithmic}[1]
\State $Q \gets \{q_\mathrm{root}\}$ \Comment{State set}
\State $\mathrm{queue} \gets [\mathrm{root}]$
\While{$\mathrm{queue}$ is not empty}
    \State $cur \gets \mathrm{queue}.\textsc{Dequeue}()$
    \For{$c \in \mathrm{cur}.\mathrm{children}$}
        \State $v \gets \mathrm{cur}.\mathrm{children}[c]$
        \State $\textsc{Append}(Q, q_v)$
        \State $\delta \gets \delta \cup (q_\mathrm{cur}, c, \varepsilon, q_v)$
        \State $\mathrm{queue}.\textsc{Enqueue}(v)$
    \EndFor
    \If{$f(\mathrm{cur}) \ne \texttt{null}$} \Comment{Add $\varphi$-arcs}
        \State $q_\mathrm{tmp} \gets q_\mathrm{cur}$
        \For{$w \in F(\mathrm{cur})$}
            \If{$w$ is the last element in $F(\mathrm{cur})$}
                \State $\delta \gets \delta \cup (q_\mathrm{tmp}, \varphi, w, q_{f(\mathrm{cur})})$
            \Else
                \State $q_\mathrm{next} \gets \text{ new state}$
                \State $\textsc{Append}(Q, q_\mathrm{next})$
                \State $\delta \gets \delta \cup (q_\mathrm{tmp}, \varphi, w, q_\mathrm{next})$
                \State $q_\mathrm{tmp} \gets q_\mathrm{next}$
            \EndIf
        \EndFor
    \EndIf
\EndWhile
\State \Return $(Q, \Sigma, \Gamma, \delta, q_\mathrm{root}, \{q_\mathrm{root}\})$ \Comment{$\mathcal{T}_{Aho}$}
\end{algorithmic}
}
\caption{%
    \hspace{-1mm}: Trie-to-Transducer Conversion \\
    \textbf{Inputs}: Trie $\mathrm{root}$, Failure Functions $f/F$, Vocabulary $\Gamma$ over $\Sigma$ \\
    \textbf{Output}: Aho-Corasick Lexicon transducer $\mathcal{T}_{Aho}$
}
\label{alg:aho_construction}
\end{algorithm}
\end{minipage}



\section{Proofs}

\projdet*

\begin{proof}
Let $\mathcal{T}$ be a transducer which recognizes Equation \ref{eq:lexicon_formulation} and was built by Algorithm \ref{alg:lexicon_construction}. By construction, each path from $q_0$ to some $q \in F$ that does not contain an $(\varepsilon, \varepsilon)$ transition (that is, it does not return to the start state) contains only a single non-$\varepsilon$ output label.

Thus, during composition, suppose there is some created state $(q, q_{start})$, where $q \in \mathcal{A}$ and $q_{start}$ is the start state of the lexicon transducer. Let $(p, q_{start})$ be a state that is reached after reading some path with exactly one non-$\varepsilon$ output label. Then, after projection, this path is a sequence of $\varepsilon$ transitions followed by a single non-$\varepsilon$ transition. This can be contracted to a single transition from from $(q, q_{start})$ to $(p, q_{start})$ labeled with the non-$\varepsilon$ label from $\Gamma$. Since each path from the start state to a final state in $\mathcal{T}$ contains a single, unique output label, there cannot be more than one path leading out of $(q, q_{start})$ with that label, thus that state has a deterministic transition function.
\end{proof}

















\begin{proposition}\label{prop:multiplicity}
Consider an automaton $\mathcal{A}$ and a single merge $G_{(a, b)}$, and a triplet of states $x, y, z \in Q$ such that $\delta(x, a) = y$, $\delta(y, b) = z$. During the composition of $\mathcal{A} \circ G_{(a, b)}$ over $x, y, z$ at most one new distinguishable state is created.
\end{proposition}

\begin{proof}
    First, we note that if there is no such triplet $x, y, z \in Q$ where $\delta(x, a) = y$, $\delta(y, b) = z$, then the composition $\mathcal{A} \circ G_{(a, b)}$ will describe exactly the same language as $\mathcal{A}$ by definition, so their minimal forms are identical and no new state is created. So, we assume that such a triplet exists. The composition of an automaton with a merge gadget must eliminate the possibility of reading $\texttt{a\textvisiblespace b}$.

    Thus, the state $y$ must be split to eliminate this sequence. Let $y'$ and $y''$ be two new states. Then, for each $c \in \delta(x)$ s.t. $c \ne a$, set $\delta(x, c) = y'$. And, for all transitions $\delta(q, c) = y$ set $\delta(q, c) = y'$. Finally, set $\delta(q, a) = y''$. Then, set $\delta(y') = \delta(y)$ and $\delta(y'', c) = \delta(y, c), \forall c \ne b$.

    By construction, all paths that passed through $y$ are preserved, except for the path from $x \rightarrow y \rightarrow z$ reading $\texttt{a\textvisiblespace b}$ and the original state $y$ can be removed (alternatively, $y'$ can be constructed from $y$ in place).
\end{proof}

\begin{remark}
Figure \ref{fig:merge_subset_example} gives an example of Proposition \ref{prop:multiplicity}.
\end{remark}


\begin{remark}
 We call $y'$ and $y''$ \textit{derived} states from the triplet $x, y, z$ as they are the states that are derived from $y$ after a merge gadget is applied and splits the state. We note that a derived state is specific to the exact triplet (i.e., the derived states of $y$ from the triplet $x, y, z$ are different from the derived states of $y$ from the the triplet $q, y, z$, where $q \ne x$).
\end{remark}


\begin{lemma}\label{lma:k_distuingishable}
Let $\mathcal{A}$ be a trim, deterministic automaton and $m_1, m_2, \dots, m_k$ be a series of merges. Assume there is a triplet of states $x, y, z \in \mathcal{A}$ and let $Y = \{y, y^1, y^2, \dots, y^l\}$ be the set of derived states of $y$ some number of times during the compositions with $\{G_{m_i}\}_{i}^k$. Then, $Y$ contains at most $k+1$ distinguishable states.
\end{lemma}
\begin{proof}
This follows directly from the determinism of $\mathcal{A}$. Since $\mathcal{A}$ is deterministic, for any merge gadget, there is at most one suitable triplet from $\{x\}\times Y \times \{z\}$ which the merge gadget can be applied to (as otherwise either $x$ or some $y' \in Y$ would contain two arcs with the same label, violating determinism). Thus, for each merge, the singular applicable triplet can be split at most once per merge according to Proposition \ref{prop:multiplicity}. Since there are at most $k$ merges, then a derived state can be split at most $k$ times, so $Y$ has a maximum cardinality of $k+1$.
\end{proof}

    So far we have only considered how successive merges act on a set triplet $x, y, z$ or a set of triplets $\{x\} \times Y \times \{z\}$ where $Y$ is the set of derived states from the triplet $x, y, z$. Now we are concerned the general case $X \times Y \times Z$. We consider this by case analysis.

\begin{lemma}\label{lma:general_case}
Let $\mathcal{A}$ be a trim, deterministic automaton (with states $Q$), $x,y, z \in Q$ be a triplet and $X, Y, Z$ be some set of derived states where $x \in X$, $y \in Y$, and $z \in Z$. Let $x', x'' \in X$, $y', y'' \in Y$, and $z', z'' \in Z$ be arbitrary states in the derived state sets. Consider a merge gadget $G_{(a, b)}$ and let $x', y', z'$ and $x'', y'', z'' \in X, Y, Z$ be two triplets of states. Then the application of $G_{(a, b)}$ to $x', y', z'$ and $x'', y'', z''$ produces at most one new indistinguishable state.
\end{lemma}

\begin{proof}
We proceed by case analysis and show that for each choice of $x^1, y^1, z^1$ and $x^2, y^2, z^2$ then $G_m$ is either not applicable over the triplet or produces exactly one new indistinguishable state. There are 8 possible cases, depending on if $x^1 \stackrel{?}{=} x^2$, etc. We assume that, if the case is possible, then the appropriate transitions for the merge $(a, b)$ exist, as otherwise it is guaranteed that no new states are added.

    \begin{enumerate}
        \item[\textbf{Case 1): }] $x^1 = x^2, y^1 = y^2, z^1 = z^2$ \\
            This case is covered by Proposition \ref{prop:multiplicity}.
        \item[\textbf{Case 2): }] $x^1 = x^2, y^1 = y^2, z^1 \ne z^2$ \\
            This is not possible, due to determinism ($y^1$ must have two arcs labeled $b$ but which go to different states, which violates the determinism of $\mathcal{A}$).
        \item[\textbf{Case 3): }] $x^1 = x^2, y^1 \ne y^2, z^1 = z^2$ \\
            This is not possible, due to determinism ($x^1$).
        \item[\textbf{Case 4): }] $x^1 = x^2, y^1 \ne y^2, z^1 \ne z^2$ \\
            This is not possible, due to determinism ($x^1$).
        \item[\textbf{Case 5): }] $x^1 \ne x^2, y^1 = y^2, z^1 = z^2$ \\
            Assume that the gadget operating on $x^1, y^1, z^1$ creates two splits $y^1$ into $q'$ and $q''$ while $x^2, y^1, z^1$ splits $y^1$ into $p', p''$. Like Proposition \ref{prop:multiplicity}, the transition functions are remapped like:        
        \begin{itemize}
            \item $\delta(x^1, c) = p', \forall c \in \{c \mid c \in \delta(x^1) \wedge c \ne a \wedge \delta(x^1, c) = y^1$\}
            \item $\delta(x^1, a) = p''$
            \item $\delta(p') = \delta(y^1)$
            \item $\delta(p'', c) = \delta(y^1, c)$, $\forall c \ne b \in \delta(y)^1$

            \item $\delta(x^2, c) = q', \forall c \in \{c \mid c \in \delta(x^2) \wedge c \ne a \wedge \delta(x^2, c) = y^1$\}
            \item $\delta(x^2, a) = q''$
            \item $\delta(q') = \delta(y^1)$
            \item $\delta(q'', c) = \delta(y^1, c)$, $\forall c \ne b \in \delta(y)^1$
        \end{itemize}

        Then, by construction $q'$ and $p'$ are indistinguishable and can be merged, and likewise for  $q''$ and $p''$. So since state $y^1$ is removed and replaced with $q'$ and $q''$, only one new state is added.

        \item[\textbf{Case 6): }] $x^1 \ne x^2, y^1 = y^2, z^1 \ne z^2$ \\
            This case is not possible, due to determinism ($y^1$).
        \item[\textbf{Case 7): }] $x^1 \ne x^2, y^1 \ne y^2, z^1 = z^2$ \\
            This case has two subcases. First, consider some merge $G_{(a', b')}$ which operated on some set of states $q, x, p$ to create $x^1$ and $x^2$. Then, $\delta(x^1, b') = \delta(x^2, b')$ for all $b' \ne d$. So if $b \ne d$, this case is impossible.

            Next, assume $b = d$, then WLOG, there cannot be an arc $\delta(x^1, b)$, as it was removed to prevent reading $\texttt{a}'\textvisiblespace \texttt{b}'$ and so this triplet is not compatible with the merge and no new states are added.

            Thus, either this case is not possible.

        \item[\textbf{Case 8): }] $x^1 \ne x^2, y^1 \ne y^2, z^1 \ne z^2$ \\
            This case is not possible, due to a combination of the reasoning of Case 7 and determinism. In short, $y^1 = y^2$ or else this is case is impossible, and if $y^1 = y^2$ then $z^1 \ne z^2$ implies $\mathcal{A}$ is not deterministic.

    \end{enumerate}

    For all 8 cases, we have shown that either a merge is not able to operate on the specified pairs of triplets, or that, regardless of the choice of triplet, only one new indistinguishable state is added.

\end{proof}






\begin{proposition}\label{prop:equivalent_compose}
\[\textsc{Min}(\textsc{Proj}(\mathcal{T}_1 \circ \mathcal{T}_2 \circ \dots \circ \mathcal{T}_n)) = \textsc{Min}(\textsc{Proj}(\dots \textsc{Min}(\textsc{Proj}(\textsc{Min}(\textsc{Proj}(\mathcal{T}_1 \circ \mathcal{T}_2)) \circ \mathcal{T}_3)) \dots \circ \mathcal{T}_n))\]
\end{proposition}

\begin{proof}
    This follows directly from the definition of composition and projection. Minimization is not relevant as it does not change the language of the transducer.
\end{proof}

\begin{proposition}\label{prop:bpe_min}
Let $\mathcal{A}$ be a trim, deterministic automaton and $G_{(a, b)}$ be a BPE merge. Then $\varepsilon\textsc{-Removal}(\textsc{Proj}(\mathcal{A} \circ G_{(a, b)}))$ is deterministic.    
\end{proposition}

\begin{proof}
Only the arc from state $0$ to $1$ has an $\varepsilon$-output. States $0$ and $2$ are output-deterministic, but state $1$ has an $a$ output transition on two arcs. However, by $\varphi$-semantics, only one of those arcs can be taken from any state by definition. Thus, at each state, there is only one valid transition per output symbol. Since $\mathcal{A}$ is also deterministic, each state has a deterministic transition function, up to $\varepsilon$-closure. There are no $\varepsilon$-cycles, and the only $\varepsilon$-transition is between state $0$ and $1$. Since state $0$ does not have $a$ as an output label (but state $1$ does) the $\varepsilon$-closure does not violate determinism.
\end{proof}

\bpesize*

\begin{proof}
Consider any triplet $x, y, z \in Q$, of which there are $|Q|^3$. By Proposition \ref{prop:multiplicity}, Lemma \ref{lma:k_distuingishable}, and Lemma \ref{lma:general_case}, each triplet can only form $k$ new states as a result of composition with $\bigcirc_i^k G_{m_i}$. As a result, the size of $|\mathcal{A}'| \in O(k|\mathcal{A}|^3)$. Proposition \ref{prop:bpe_min} shows that any $\textsc{Min}(\textsc{Proj}(A \circ G_m))$ can be done in polynomial time. Thus, via induction, following Proposition \ref{prop:equivalent_compose}, $\textsc{Min}(\textsc{Proj}(\mathcal{A}' \circ G_{\mu_k}))$ can be computed in $O(k|\mathcal{A}|^3)$ time by iteratively computing $\textsc{Min}(\textsc{Proj}(\dots\textsc{Min}(\textsc{Proj}(\textsc{Min}(\textsc{Proj}(\mathcal{A} \circ G_{m_1})) \circ G_{m_2})) \dots \circ G_{m_k}))$. The maximum size of any intermediate automaton is $O(k|\mathcal{A}^3|)$ and so composition, projection, and minimization can be done in polynomial time.
\end{proof}

\bpesizecorollary*

\begin{proof}
Let $k = |\mu|$. Note $|\mu| \in O(|\Gamma|)$ by definition. Theorem \ref{thm:bpe_complexity} shows that \[\textsc{Min}\left(\textsc{Proj}\left(\mathcal{A} \circ \left( \mathop{\bigcirc}\limits_{(a,b) \in \mu} G_{(a,b)} \right) \right)\right)\] can be computed in $\textsc{Poly}(|\mathcal{A}|, |\mu|, |\Gamma|)$ time. This implies the size of the output must also be polynomial in $|\mathcal{A}|$ and $|\Gamma|$.
\end{proof}


