\subsubsection{FL}
As for FL, the global objective of FL is to learn an FL global model with the minimum global training loss, i.e., 
{
\begin{equation} \small
    \label{GlobalObj}
    \underset{\boldsymbol{\omega}}{\min}\, F(\boldsymbol{\omega})={\sum}_{n=1}^{N}p_nF_n(\boldsymbol{\omega})  \,,
\end{equation}}%
where $\boldsymbol{\omega}\in\mathbb{R}^{ |\boldsymbol{\omega}|}$ is the model parameter with $|\boldsymbol{\omega}|$ elements; $F(\cdot)$ is the global loss function, 
% as given by
% \begin{equation}
%     \label{g_loss}
%     F(\boldsymbol{\omega})={\sum}_{n=1}^{N}p_nF_n(\boldsymbol{\omega}) \,,
% \end{equation}
and $F_{n}(\cdot)$ is the local loss function of client $n \in \mathcal{N}$; $p_{n}\triangleq\frac{\left|\mathcal{D}_{n}\right|}{\left|\mathcal{D}\right|}$ is the aggregation coefficient for client $n$, with ${\sum}_{n=1}^{N}p_n=1$. 
For illustration convenience, we assume the size of each client's local dataset is the same, i.e., $p_n=\frac{1}{N}$.

According to 
% (\ref{objective_p})--
(\ref{GlobalObj}), on each communication round, an FL local model, denoted by $\boldsymbol{u}_n^t$, is trained at every selected client $n$, followed by clipping, DP perturbation, and quantization, before the client uploads the FL local model to the server. 


\textbf{Clipping}: 
The FL local models are clipped as
{
 	\begin{equation} \small
    \boldsymbol{u}_{n}^{t}=\boldsymbol{u}_{n}^{t}\Big/\max\big(1,{\| \boldsymbol{u}_{n}^{t}\|}\big/{C}\big)  \,,
    \label{clipping} 
	\end{equation}}%
 where $C$ is the pre-determined clipping threshold ensuring that the local model parameter $\parallel \boldsymbol{u}_{n}^{t}\parallel \leq C$~\cite{yuan2023amplitude}.


 \textbf{DP perturbation:}
 % The DP noise is added after a client clips its FL local model.
  Let $\mathbf{z}_n^t$ denote the independent and identically distributed (i.i.d.) Gaussian noise added by client $n$ to its local model $\boldsymbol{u}_{n}^{t}$ at the $t$-th communication round. Each element in $\mathbf{z}_n^t$ follows $\mathbb{N}(0,\sigma_\mathrm{DP}^2)$.

  \begin{definition}[$(\epsilon,\delta)$-DP]
A privacy preserving mechanism $\mathcal{M}:\mathcal{X}\rightarrow \mathcal{R}$ is $(\epsilon,\delta)$-DP if, for any two adjacent datasets $\mathcal{X}_{0}$, $\mathcal{X}_{1}\in \mathcal{X}$ and any subset of outputs $S\subseteq \mathcal{R}$, it holds that
\begin{equation} \small
    \label{DefDP}
    \Pr\left[\mathcal{M}\left(\mathcal{X}_{0}\right)\in\mathcal{S}\right]\leq e^{\epsilon}\Pr\left[\mathcal{M}\left(\mathcal{X}_{1}\right)\in\mathcal{S}\right]+\delta  \,,
\end{equation}
where $\epsilon>0$ specifies the difference beyond which the outputs concerning $\mathcal{X}_{0}$ and $\mathcal{X}_{1}$ can be differentiated, and $\delta \in[0,1]$ is the probability with which
the ratio between the probabilities of $\mathcal{X}_{0}$ and $\mathcal{X}_{1}$ is no smaller then $e^\epsilon$.
\end{definition}
\begin{definition}[Max Divergence]
The Max Divergence, also known as the $\infty$-th order of $R\acute{e}nyi$ divergence, between two random variables $Y$ and $Z$ taking values from the same sample space $\mathcal{Y}$ is defined as
{\begin{equation}  \small
D_{\infty}(Y||Z)=\max_{y\in \mathcal{Y}}\left[\ln\frac{\Pr\left[Y=y\right]}{\Pr\left[Z=y\right]}\right].
    \end{equation}}%
The $\delta$-Approximate Max Divergence 
% between $Y$ and $Z$ 
is defined as
{\begin{equation} \small
D_{\infty}^{\delta}(Y||Z)=\max_{y\in \mathcal{Y}}\left[\ln\frac{\Pr\left[Y=y\right]-\delta}{\Pr\left[Z=y\right]}\right].
    \end{equation}}%
The randomized mechanism $\mathcal{M}:\mathit{\mathcal{D\rightarrow R}}$ satisfies $\epsilon$-DP if $D_{\infty}\left[\mathcal{M}\left({\mathcal{X}_{0}}\right)||\mathcal{M}\left({\mathcal{X}_{1}}\right)\right]\leq \epsilon$ for all measurable sets $\mathcal{Y}\subseteq\mathcal{R}$ and any two adjacent datasets ${\mathcal{X}_{0}},{\mathcal{X}_{1}}\in\mathcal{D}$. 
Moreover, $\mathcal{M}$ satisfies $(\epsilon,\delta)$-DP if 
% for all measurable sets $\mathcal{Y}\subseteq\mathcal{R}$ and for any two adjacent databases ${\mathcal{X}_{0}},{\mathcal{X}_{1}}\in\mathcal{D}$, 
$D_{\infty}^{\delta}\left[\mathcal{M}\left({\mathcal{X}_{0}}\right)||\mathcal{M}\left({\mathcal{X}_{1}}\right)\right]\leq \epsilon$\cite{dwork2014algorithmic}.
\end{definition}
