\label{P_C3}
& \textbf{C2}: {\sum}_{k=1}^{K}c_{n,k}^{t}\leq1,\,\forall n\in\mathcal{N}, \\
& \textbf{C3}: {\sum}_{n=1}^{N}c_{n,k}^{t}\leq1,\,\forall k\in\mathcal{K}, \\
& \textbf{C4}:
P_{n}^{t}\leq P_{n}^{\mathrm{th}},\,\forall n\in\mathcal{N}, \\
\label{P_C6}
& \textbf{C5}:
r_{n,k}^{t}\geq r_{\mathrm{min}},\forall k\in\mathcal{K},\\
& \textbf{C6}:
c_{n,k}^{t}\in\{0,1\},\forall n\in\mathcal{N},k\in\mathcal{K},\\
\label{P_C8}
& \textbf{C7}:
{\sum}_{t'=1}^{t}{\sum}_{k=1}^{K}c_{n,k}^{t'}\leq T_{0},\,\forall n\in\mathcal{N},\\
% \label{P_C9}
% & \textbf{C9}:
