\label{P_C9}
& \textbf{C8}:
0<\lambda_{n}^{t+1}<2,\forall n\in\mathcal{N},\\
\label{P_C10}
& \textbf{C9}:
0<\eta_{\mathrm{P},n}^{t+1}<1,\forall n\in\mathcal{N},\\
\label{P_C11}
& \textbf{C10}:
0<\eta_{\mathrm{F},n}^{t}<1,\forall n\in\mathcal{N},\\
\label{P_C12}
& \textbf{C11}:
0<\varepsilon_{\mathrm{F},n}^{t}<1,\forall n\in\mathcal{N},
