\subsection{Client Selection, Channel Allocation, and Power Control}
\label{client_selection}
%\subsection{Robustness of Privacy-Preserving FL}
We first minimize $\Phi_n^t$ per client $n \in \cal{N}$ by minimizing $\Theta_{\mathrm{L}}^{t}$:
% \begin{subequations}
% \label{P2}
    \begin{align}
\textbf{P2}:  \quad\min_{\mathbf{c}^{t},\mathbf{p}^{t}}  \;\Theta_{\mathrm{L}}^{t},\quad
\textrm {s.t. }\,\eqref{P_C3}-\eqref{P_C8} \nonumber.
\end{align}
% \end{subequations}
Clearly, the data rate $r_{n,k}^{t}$ increases monotonically with $P_{n}^{t}\leq P_{n}^{\mathrm{th}}$, while the element error probability $\rho_{n,\mathrm{L}}^{t}$ decreases.
Therefore, the optimal transmit power of client $n \in \mathcal{N}_{t}$ is $P_{n}^{t}=P_{n}^{\mathrm{th}}$. Let $\Upsilon_{n}^{t}$ denote the number of rounds that client $n$ is selected for uploading before round $t$, and $\mathcal{N}_{t}^{\mathrm{a}}$ collect the clients allowed to upload local models at round $t$, i.e., $\mathcal{N}_{t}^{\mathrm{a}}=\{n|n\in \mathcal{N}, \Upsilon_{n}^{t}<T_0\}$. Problem \textbf{P2} can be rewritten as
\begin{subequations}\small
\label{P3}
    \begin{align}
\textbf{P3}: \quad & \min_{\mathbf{c}^{t}}\;{\sum}_{n\in\mathcal{N}}\rho_{n,\mathrm{L}}^{t}\\
\textrm {s.t. }  \quad & {\sum}_{k=1}^{K}c_{n,k}^{t}\leq1,\,\forall n\in\mathcal{N}_{t}^{\mathrm{a}},\\
% &\sum_{k=1}^{K}c_{n,k}^{t}=0,\,\forall n\in\mathcal{N}/\mathcal{N}_{t+1}^{\mathrm{a}},\\
&{\sum}_{n=1}^{N}c_{n,k}^{t}\leq1,\,\forall k\in\mathcal{K},\\
&c_{n,k}^{t}\in\{0,1\},\forall n\in\mathcal{N}_{t}^{\mathrm{a}},k \in \mathcal{K},\\
&\eqref{P_C6}. \nonumber
\end{align}
\end{subequations}
Problem \textbf{P3} can be interpreted as a maximum-weight matching problem in bipartite graphs, which can be optimally solved using the Kuhn-Munkres (KM) algorithm\cite{kuhn1955hungarian}. At round $t$, the minimum of $\Theta_{\mathrm{L}}^{t}$, denoted as $\Theta_{\mathrm{L},\min}^{t}$, is obtained with the optimal client selection, channel allocation, and power control.

