 \begin{algorithm}[t]
    \caption{Proposed Transmission Scheduling Policy}
    \label{algorithm2}
    \begin{algorithmic}[1]
        \Require $T_0$, $\{t_n=0\}_{n\in\mathcal{N}}$, $r_{\mathrm{min}}$, $\{P_n^{\mathrm{th}}\}_{n \in \mathcal{N}}$, $\varepsilon_{\mathrm{P}}$, $h_0^{0}$.
        \Ensure $\mathbf{c}^{t}$, $\mathbf{p}^{t}$, $\boldsymbol{\eta}_{\mathrm{F}}^{t}$, $\boldsymbol{\eta}_{\mathrm{P}}^{t+1}$, $\boldsymbol{\lambda}^{t+1}$, $\forall t$.
        \While{$\{n \mid t_n \leq T_0, n \in \mathcal{N}\} \neq \emptyset$}
            \State {$//$Client selection, channel allocation, power control}
            \State Let $P_n^t = P_n^{\mathrm{th}}$, $\forall n \in \mathcal{N}$;
            \State Obtain the set of candidate clients $\mathcal{N}_{t}^{\mathrm{a}}$ and $\{\rho_{n,\mathrm{L}}^{t}\}_{n \in \mathcal{N}}$ according to (\ref{SNR})-(\ref{element_error_pr});
            \State Obtain the optimal client selection $\mathcal{N}_{t}$ and channel allocation $\mathbf{C}^{t}$ by solving Problem \textbf{P3} using KM algorithm; 
            \State $t_n \leftarrow t_n + 1$, $\forall n \in \mathcal{N}_{t}$;
            \State $//$ Learning rate and weighting coefficient adjustment
            \State Set $\eta_{\mathrm{F},n}^{t}=\frac{\mu}{2(1+\phi_{1})L^{2}}$ and $\varepsilon_{\mathrm{P}}^{t+1}=\varepsilon_{\mathrm{P}}$;
            \ParFor{$n \in \mathcal{N}$}
                % \If{$\varepsilon_{\mathrm{P}}^{t+1} \in (2 - \mu, 1)$}
                    \State Obtain the optimal PL learning rate $\eta_{\mathrm{P},n}^{t+1,*}$ by solving Problem \textbf{P7}; 
                % \ElsIf{$\varepsilon_{\mathrm{P}}^{t+1} \in [1 - \frac{\mu^{2}}{4}, 2 - \mu]$}
                %     \State Obtain the optimal PL rate $\eta_{\mathrm{P},n,0}^{t+1}$ and $\eta_{\mathrm{P},n,1}^{t+1}$ by minimizing $\Phi_{n}^{t+1}$ on $\Omega_0^{t+1}$ and $\Omega_1^{t+1}$, using Newton's Method separately
                %     \State Obtain the optimal $\eta_{\mathrm{P},n}^{t+1,*} = \underset{\eta_{\mathrm{P},n}^{t+1}}{\arg\min}\{\Phi_{n}^{t+1}\mid_{\eta_{\mathrm{P},n,0}^{t+1}}, \Phi_{n}^{t+1}\mid_{\eta_{\mathrm{P},n,1}^{t}}\}$
                % \EndIf
                \State Obtain the optimal weighting coefficient $\lambda_{n}^{t+1,*}$ based on (\ref{lambda}) and $\eta_{\mathrm{P},n}^{t+1,*}$;
            \EndParFor
            % \State Set $h_{0}$ as the lower bound of (\ref{vL_c2}), and obtain the optimal local learning rates $\eta_{\mathrm{F},n}^{t}$ by solving (\ref{eta_G}) in parallel;
            \State $t \leftarrow t + 1$.
        \EndWhile
    \end{algorithmic}
\end{algorithm}

