        \\
        D_{\infty}^{\delta}\left[\mathcal{M}\left({\mathcal{X}_{1}'}\right)||\mathcal{M}\left({\mathcal{X}_{1}}\right)\right]&=\max_{\chi\in\mathcal{Q_{\mathrm{L}}}}\ln\frac{p-\delta}{p_{1}},
