    \begin{subequations} \footnotesize
    \label{budget_one_round}
        \begin{align}
        D_{\infty}\left[\mathcal{M}\left(\mathcal{X}_{1}'\right)||\mathcal{M}\left({\mathcal{X}_{1}}\right)\right]\!&\leq\! \max\{\ln\frac{\psi}{\psi_{1}},\ln\frac{\psi'}{\psi_{1}'}\},
            \\
           D_{\infty}^{\delta}\left[\mathcal{M}\left({\mathcal{X}_{1}'}\right)||\mathcal{M}\left({\mathcal{X}_{1}}\right)\right]\!&\leq \!\max\{\ln\frac{\psi\!\!-\!\!\delta}{\psi_{1}} ,\ln\frac{\psi'\!\!-\!\!\delta}{\psi_{1}'} \}\!\!=\!\!\epsilon_\mathrm{Q},\nonumber
           \\
