\section{System Model}

We present a federated SC framework for bandwidth-constrained IoT networks consisting of $K$ distributed clients and a central aggregation server. Each client $k \in \{1, 2, \ldots, K\}$ maintains a private image dataset $\mathcal{D}_k$ and participates in collaborative training without sharing raw data. The global dataset $\mathcal{D} = \bigcup_{k=1}^K \mathcal{D}_k$ is distributed across clients using a Dirichlet distribution with concentration parameter $\alpha > 0$ to simulate non-IID conditions typical of real-world IoT deployments. Each local dataset $\mathcal{D}_k = \{\mathbf{x}_k^{(i)}\}_{i=1}^{|\mathcal{D}_k|}$ contains images $\mathbf{x}_k^{(i)} \in \mathbb{R}^{C \times H \times W}$, where $C$ denotes the number of channels ({\it e.g.}, $C=3$ for RGB) and $H \times W$ represents the spatial dimensions. The heterogeneous data distribution ensures that clients possess varying quantities of images with different statistical properties, reflecting practical scenarios where IoT devices capture data under diverse conditions.

\subsection{Semantic Communication Architecture}

Each client implements an end-to-end SC system parameterized by $\boldsymbol{\Theta} = \{\boldsymbol{\theta}_{\text{se}}, \boldsymbol{\theta}_{\text{ce}}, \boldsymbol{\theta}_{\text{cd}}, \boldsymbol{\theta}_{\text{sd}}\}$, comprising semantic encoder, channel encoder, channel decoder, and semantic decoder parameters. The SC system operates through five stages as detailed below:

\paragraph{Semantic Encoding} The encoder $f_{\text{se}}(\cdot; \boldsymbol{\theta}_{\text{se}})$ extracts task-relevant features while preserving reconstruction-critical information:
\begin{equation}
\mathbf{z}, \mathcal{S} = f_{\text{se}}(\mathbf{x}; \boldsymbol{\theta}_{\text{se}}),
\end{equation}
where $\mathbf{z} \in \mathbb{R}^{d_s}$ represents the semantic bottleneck with dimension $d_s \ll C \cdot H \cdot W$, providing a compact representation of the input image $\mathbf{x} \in \mathbb{R}^{C \times H \times W}$.  The set $\mathcal{S} = \{\mathbf{s}_1, \mathbf{s}_2\}$ denotes intermediate feature maps preserved for skip connections.

\paragraph{Channel Encoding} The encoder $f_{\text{ce}}(\cdot; \boldsymbol{\theta}_{\text{ce}})$ further compresses semantic features:
\begin{equation}
\mathbf{x}_c = f_{\text{ce}}(\mathbf{z}; \boldsymbol{\theta}_{\text{ce}}),
\end{equation}
where $\mathbf{x}_c \in \mathbb{R}^{d_c}$ represents the transmitted symbols with $d_c < d_s$, achieving compression ratio $\rho = d_s/d_c$.

\paragraph{Wireless Transmission} The channel introduces Rayleigh fading and additive white Gaussian noise (AWGN):
\begin{equation}
\mathbf{y}_c = \mathbf{h} \odot \mathbf{x}_c + \mathbf{n},
\end{equation}
where $\mathbf{h} \in \mathbb{C}^{d_c}$ contains independent complex Gaussian fading coefficients with $h_i \sim \mathcal{CN}(0, 1)$, $\mathbf{n} \sim \mathcal{CN}(\mathbf{0}, \sigma^2\mathbf{I})$ represents AWGN, and $\odot$ denotes element-wise multiplication. The noise variance is $\sigma^2 = 10^{-\gamma/10}$ for signal-to-noise ratio (SNR) $\gamma$ in dB.

\paragraph{Channel Decoding} Zero-forcing equalization recovers the transmitted symbols:
\begin{equation}
\hat{\mathbf{x}}_c = \mathbf{y}_c \oslash (\mathbf{h} + \epsilon),
\end{equation}
where $\oslash$ denotes element-wise division and $\epsilon$ ensures numerical stability. The channel decoder reconstructs semantic features:
\begin{equation}
\hat{\mathbf{z}} = f_{\text{cd}}(\hat{\mathbf{x}}_c; \boldsymbol{\theta}_{\text{cd}}).
\end{equation}

\paragraph{Semantic Decoding}
Finally, the semantic decoder combines recovered features with skip connections  to reconstruct the image:
\begin{equation}
\hat{\mathbf{x}} = f_{\text{sd}}(\hat{\mathbf{z}}, \mathcal{S}; \boldsymbol{\theta}_{\text{sd}}).
\end{equation}

\subsection{Federated Learning Protocol}
\label{sec:fl-protocol}

\subsubsection{Overview}
The framework operates over $T$ rounds, with the server orchestrating collaborative training through adaptive client selection. Algorithm~\ref{alg:fed_semcom} presents the complete protocol. In each round $t$, the server first selects a subset $\mathcal{S}_t \subseteq \{1, \ldots, K\}$ of clients and assigns each selected client $k$ a specific number of local training epochs $E_k^{(t)}$ based on the chosen strategy (detailed in Section~\ref{sec:client-select}). The server then broadcasts the current global model $\boldsymbol{\Theta}^{(t-1)}$ to all selected clients.

\begin{algorithm}[ht]
\caption{Federated SC with Client Selection}
\label{alg:fed_semcom}
\begin{algorithmic}[1]
\STATE Initialize global model $\boldsymbol{\Theta}^{(0)}$, participation counts $\mathbf{n} = \mathbf{0}$
\FOR{round $t = 1, \ldots, T$}
\STATE Select subset $\mathcal{S}_t \subseteq \{1, \ldots, K\}$ and epochs $\{E_k^{(t)}\}_{k \in \mathcal{S}_t}$ via client selection strategy
\STATE Broadcast $\boldsymbol{\Theta}^{(t-1)}$ to all clients in $\mathcal{S}_t$
\FOR{each client $k \in \mathcal{S}_t$ \textbf{in parallel}}
\STATE $\boldsymbol{\Theta}_k^{(t)} \leftarrow$ \textsc{LocalTrain}($\boldsymbol{\Theta}^{(t-1)}$, $\mathcal{D}_k$, $E_k^{(t)}$)
\STATE $\mathcal{L}_k^{(t)} \leftarrow$ average loss on $\mathcal{D}_k$ using $\boldsymbol{\Theta}_k^{(t)}$
\ENDFOR
\STATE Update participation: $n_k \leftarrow n_k + 1$ for all $k \in \mathcal{S}_t$
\STATE $\boldsymbol{\Theta}^{(t)} \leftarrow$ \textsc{FedAggregate}($\{\boldsymbol{\Theta}_k^{(t)}\}_{k \in \mathcal{S}_t}$, $\{\mathcal{L}_k^{(t)}\}_{k \in \mathcal{S}_t}$)
\ENDFOR
\RETURN Final model $\boldsymbol{\Theta}^{(T)}$
\end{algorithmic}
\end{algorithm}

Each client $k \in \mathcal{S}_t$ performs local optimization on its private dataset $\mathcal{D}_k$ (detailed in Section~\ref{sec:local-optim}), producing updated parameters $\boldsymbol{\Theta}_k^{(t)}$ and reporting its average training loss $\mathcal{L}_k^{(t)}$. After local training completes, the server aggregates client contributions using the \textsc{FedAggregate} procedure shown in Algorithm~\ref{alg:fedaggregate}. 

Our aggregation mechanism employs loss-based weighting to naturally adapt to client heterogeneity. The weight formula $w_k = \frac{1}{|\mathcal{S}_t| - 1}(1 - \frac{\mathcal{L}_k}{\mathcal{L}_{\text{total}}})$ assigns higher weights to clients with lower training loss, effectively prioritizing models that achieve better local performance. This approach offers several advantages: (i) it automatically accounts for data quality differences without requiring explicit data statistics, (ii) it adapts dynamically as client performance evolves during training, and (iii) it requires no additional hyperparameter tuning. Unlike standard FedAvg which treats all clients equally, our loss-based aggregation naturally handles non-IID data distributions by giving more influence to clients whose local data leads to better model convergence.

\begin{algorithm}[ht]
\caption{\textsc{FedAggregate} Procedure}
\label{alg:fedaggregate}
\begin{algorithmic}[1]
\REQUIRE Client models $\{\boldsymbol{\Theta}_k\}_{k \in \mathcal{S}_t}$, losses $\{\mathcal{L}_k\}_{k \in \mathcal{S}_t}$
\STATE Compute total loss: $\mathcal{L}_{\text{total}} \leftarrow \sum_{k \in \mathcal{S}_t} \mathcal{L}_k$
\FOR{each client $k \in \mathcal{S}_t$}
\STATE $w_k \leftarrow \frac{1}{|\mathcal{S}_t| - 1} \left(1 - \frac{\mathcal{L}_k}{\mathcal{L}_{\text{total}} + \epsilon}\right)$, where $\epsilon = 10^{-8}$
\ENDFOR
\STATE $\boldsymbol{\Theta} \leftarrow \sum_{k \in \mathcal{S}_t} w_k \cdot \boldsymbol{\Theta}_k$
\RETURN Aggregated model $\boldsymbol{\Theta}$
\end{algorithmic}
\end{algorithm}

\subsubsection{Local Optimization}
\label{sec:local-optim}

During round $t$, each selected client $k \in \mathcal{S}_t$ performs $E_k^{(t)}$ epochs of local optimization to minimize the following objective:
\begin{equation}
\min_{\boldsymbol{\Theta}} \frac{1}{|\mathcal{D}_k|} \sum_{\mathbf{x} \in \mathcal{D}_k} \mathcal{L}(\mathbf{x}, \hat{\mathbf{x}}) + \mu \|\boldsymbol{\Theta}\|_2^2,
\end{equation}
where $\hat{\mathbf{x}} = f_{\text{SC}}(\mathbf{x}; \boldsymbol{\Theta})$ represents the reconstructed image through the complete SC system (encoding, transmission, and decoding), and $\mu$ is the weight decay coefficient for regularization. The reconstruction loss $\mathcal{L}$ combines two complementary objectives:
\begin{equation}
\label{eq:reconst-loss}
\mathcal{L}(\mathbf{x}, \hat{\mathbf{x}}) = \alpha \|\mathbf{x} - \hat{\mathbf{x}}\|_2^2 + (1 - \alpha) \|\mathbf{x} - \hat{\mathbf{x}}\|_1,
\end{equation}
where $\alpha \in [0,1]$ balances between $\ell_2$ norm for smooth reconstruction and $\ell_1$ norm for robustness to outliers and preservation of sharp edges.

Training proceeds via gradient-based optimization with mini-batches of size $B$. To ensure stable convergence in the presence of noisy gradients from channel effects, we apply gradient clipping:
\begin{equation}
\nabla \boldsymbol{\Theta} \leftarrow \min\left(1, \frac{\tau}{\|\nabla \boldsymbol{\Theta}\|_2}\right) \nabla \boldsymbol{\Theta},
\end{equation}
where $\tau$ is the clipping threshold. After completing $E_k^{(t)}$ epochs, client $k$ transmits its updated model parameters $\boldsymbol{\Theta}_k^{(t)}$ and average training loss $\mathcal{L}_k^{(t)}$ back to the server for aggregation.

