\begin{algorithm}
\caption{IMU Rotation Diversity}
\label{alg:rotation diversity}
\KwData{A sequence of IMU Rotation $\{R_{\rm IMU}(1),...,R_{\rm IMU}(n)\}$.}
\KwResult{Rotation Diversity $RD$.}
Initialize discrete Euler angle space $\mathbf{S} \in \mathbb{R}^{24 \times 12 \times 24}$ with $\mathbf{S}_{i,j,k} = 0$  $\forall i,j,k$\;
\For{$t=1$ \textbf{to} $n$}{
    $i,j,k \gets$ Calculate the coordinates of $R_{\rm IMU}(t)$ in $\mathbf{S}$\;
    $\mathbf{S}_{i,j,k} \gets \mathbf{S}_{i,j,k} + 1$\;
}
$RD \gets$ Count($\mathbf{S}_{i,j,k} > 0$);
\end{algorithm}
\subsection{Dynamic Calibration in Motion Capture}
Based on the TIC network and aforementioned rotation diversity, we have incorporated dynamic calibration into the existing inertial motion capture system (Alg.~\ref{alg:dynamic calibration}).
It is worth noting that for each IMU in the system, we independently calculate $RD$, and if the calibration is triggered, the TIC network will calculate $R_{G^{'}G}$ and $R_{BS}$ for all IMUs, but only calibrate those whose $RD$ exceeds the threshold $T_R$.
\begin{algorithm}
\caption{Dynamic Calibration in Motion Capture}
\label{alg:dynamic calibration}
\KwData{Data index $i=1$, Uncalibrated IMU orientation and acceleration readings $\{R_{\text{IMU}}(1),R_{\text{IMU}}(2),...\}$, $\{a_{\text{IMU}}(1),a_{\text{IMU}}(2),...\}$, Data Buffer $B_n$ with maximum length = $n$, Trained TIC Network $TIC$, Rotation diversity threshold $T_R$. Timing signal at intervals of \textit{t} seconds $S_{t}$. }
\KwResult{Calibrated IMU readings $\hat{R}_{\text{IMU}}$, $\hat{a}_{\text{IMU}}$.}
Initialize $R_{G^{'}G}$ and $R_{BS}$ with identity matrix $I$\;
\While{True}{
    $\hat{R}_{\text{IMU}}(i), \hat{a}_{\text{IMU}}(i) \gets$ Calibrate ${R}_{\text{IMU}}(i), {a}_{\text{IMU}}(i)$ using $R_{G^{'}G}$ and $R_{BS}$ (Eq.~\ref{eq:imu_calibration})\;
    $B_n$.append($R_{\rm IMU}^{(i)}$, $a_{\rm IMU}^{(i)}$)\;
    \If{$|B_n|==n$ and $S_{t}==\text{True}$}{
       $\textbf{R}_{\rm IMU}^{1\rightarrow n},\textbf{a}_{\rm IMU}^{1\rightarrow n}\gets$  $B_n$\;
        // \textcolor{gray}{Remove the known drift and offset.}\\
        $\textbf{R}_{\rm IMU}^{1\rightarrow n}, \textbf{a}_{\rm IMU}^{1\rightarrow n}\gets {R_{G^{'}G}^{T}} \cdot\textbf{R}_{\rm IMU}^{1\rightarrow n} \cdot R_{BS}^{T}$,  ${R_{G^{'}G}^{T}}\cdot\textbf{a}_{\rm IMU}^{1\rightarrow n}$\;
        // \textcolor{gray}{Estimating the unknown changes.}\\
        $\Delta R_{G^{'}G}$, $\Delta R_{BS} \gets$  $TIC(\textbf{R}_{\rm IMU}^{1\rightarrow n}$,  $\textbf{a}_{\rm IMU}^{1\rightarrow n})$\;
        $RD\gets$ RotationDiversity($B_n$)\;
        // \textcolor{gray}{Update drift and offset matrices.}\\
        \If{$RD>T_R$}{
            $R_{G^{'}G}\gets$ $R_{G^{'}G} \cdot \Delta R_{G^{'}G}$\;
            $R_{BS}\gets$ $\Delta R_{BS} \cdot R_{BS}$\;
        }
        $B_n$.clear()\;
    }
    i $\gets$ i + 1\;
}
\end{algorithm}

\section{Experiments}
\subsection{Training Data Synthesis}
\label{sec:synthetic_dataset}
Uncalibrated IMU data and their corresponding $R_{G^{'}G}(t)$ and $R_{BS}(t)$ data are necessary to train the TIC network. However, the cost of collecting such dataset is prohibitive because $R_{G^{'}G}(t)$ and $R_{BS}(t)$ are vary randomly during device usage, which cannot be manually controlled to collect sufficient samples.

To address this challenge, we adopted a data synthesis approach to obtain the required training data. Firstly, we need well-calibrated IMU data $\mathcal{D}_{\rm IMU}^{\rm cali}$. Similarly to works in inertial motion capture, the $\mathcal{D}_{\rm IMU}^{\rm cali}$ we used includes both synthetic data based on AMASS~\cite{mahmood2019amass} and real-world data from the DIP~\cite{huang2018deep} dataset, which helps the TIC network adapt to the characteristics of the real IMU signal.
Then, we simulated uncalibrated IMU data based on Assum.~\ref{assump:Short-term Static Assumption}.
Specifically, for each IMU data sequence (256 frames at 30Hz, 8.53s) in $\mathcal{D}_{\rm cali}$, we use random Euler angle transformations to create $R_{G^{'}G}$ and $R_{BS}$ and apply them to each frame in a sequence. These Euler angles were extensively sampled from a uniform distribution within fixed intervals (see supplementary materials) to cover all possible cases.


% The reason we using uniform distribution is that the distribution of $R_{G^{'}G}$ and $R_{BS}$ is quite vary across different usage scenarios (e.g. uncertain magnetic field interference and calibration pose error~\cite{yi2024pnp}), thus, we do not make any prior assumptions about distribution function and perform extensive sampling from a uniform distribution to cover all possible cases.

It is worth noting that $R_{\rm IMU}$ and $a_{\rm IMU}$ for each batch of data are synthesized on demand during model training.
Compared to using a pre-synthesized dataset of fixed/limited size, this can provide a more diverse set of $R_{G^{'}G}$ and $R_{BS}$ samples.


\subsection{Test Data Collection}

We recruited 5 volunteers (3 male, 2 female) to collect the real-world dataset. All these volunteers have experience with using inertial motion capture devices and are familiar with the process of Static Calibration. Volunteers were asked to wear both optical motion capture suits and 6 IMUs simultaneously, placed on the left forearm, right forearm, left lower leg, right lower leg, head, and hips (see Fig.~\ref{fig:hardware}). All 6 IMUs are integrated with 3 optical markers, allowing the absolute orientation and acceleration of IMUs to be captured.
