    \centering
    \includegraphics[width=0.48\textwidth]{Figs/fig_ego-yaw.pdf}
    \caption{Decompose of the coordinate drift based on the ego-yaw coordinate system.}
    \label{fig:ego-yaw}
\end{figure}

